(window.SITE_LANG_DATA = window.SITE_LANG_DATA || {})["mt"] = {"ui":{"skip":"Aqbeż għall-kontenut","back":"← Lura għal AI-gile","lang.button":"Lingwa: {name}","lang.dialog":"Agħżel lingwa","lang.search":"Fittex lingwa","lang.none":"Ebda lingwa ma taqbel","lang.notYet":"Għad m'hemmx traduzzjoni għal {name}","theme.aria":"Aqleb it-tema: ċara, skura jew sewda","theme.toLight":"Aqleb għat-tema ċara","theme.toDark":"Aqleb għat-tema skura","theme.toBlack":"Aqleb għat-tema sewda (iswed veru, faċli fuq skrins OLED)","words.underline":"Issottolinja dawn il-kliem fil-paġna","words.underlineHelp":"Għaddi l-maws minn fuq kelma b'linja ta' tikek, jew agħfasha, biex tara xi tfisser.","words.col.todo":"Karti magħżula għalissa: it-tim se jibda minn dawn wara.","words.col.doing":"AI qed taħdem fuq din il-karta bħalissa.","words.col.review":"AI waħda lestiet ix-xogħol; oħra tivverifikah qabel ma jaslilek.","words.col.verify":"Qed jistenniek: ippruvah u għid jekk jaħdimx.","words.col.team":"In-noti jew it-tweġibiet tiegħek, qed jistennew li t-tim jerfagħhom.","words.col.done":"Lest u aċċettat.","index.title":"AI-gile: it-tim tal-iżvilupp tiegħek tal-AI, fuq bord wieħed","index.description":"AI-gile huwa bord kanban għal timijiet tal-kodiċi bl-AI. Jaħdmu waqt li torqod; inti tirċievi munzell wieħed qasir ta' affarijiet biex tiddeċiedi, tittestja u taċċetta.","hero.logoAlt":"Ikona tal-bord ta' AI-gile","hero.h1.html":"It-tim tal-iżvilupp tiegħek tal-AI, fuq bord&nbsp;wieħed.","hero.alpha":"🐣 Pre-alpha magħluqa","hero.alphaTitle":"Bikri u mhux lest: grazzi li qed tipprova!","hero.lede":"Jibnu waqt li torqod. Tqum għal munzell wieħed qasir: ftit mistoqsijiet, ftit affarijiet biex tittestja, djamant vjola jew tnejn. Ikklikkja, aċċetta, u lura għall-kafè tiegħek.","dl.windows":"Applikazzjoni għal Windows","dl.browser":"Mexxiha fil-browser tiegħek","dl.messenger":"📱 Messenger għat-telefon tiegħek","dl.soon":"Dalwaqt","dl.notify":"🔔 Għarrafni meta tiftaħ","dl.notifySmall":"Alpha jew beta","hero.secondary":"Agile, imma t-tim qatt ma jeħtieġ kafè għall-istand-up. (Jagħmlu l-istand-ups xorta waħda.)","pitch.h2":"AI-gile fi kliem kemm trid","pitch.lede":"Agħżel tul, minn kelma waħda sa 144. Kull tul huwa deskrizzjoni waħedha, miktuba għal dak id-daqs. Iġbed is-slider jew uża t-tasti tal-vleġeġ.","pitch.rangeLabel":"Tul f'kliem","pitch.dice":"🎲 verżjoni oħra","pitch.words.one":"{n} kelma","pitch.words.other":"{n} kelma","pitch.letters.one":"{n} ittra","pitch.letters.other":"{n} ittra","pitch.chars.one":"{n} karattru","pitch.chars.other":"{n} karattru","count.line.html.one":"{n} karta fuq il-bord bħalissa","count.line.html.other":"{n} karta fuq il-bord bħalissa","people.humans.html.one":"👥 {n} bniedem","people.humans.html.other":"👥 {n} bniedem","people.agents.html.one":"🤖 {n} aġent","people.agents.html.other":"🤖 {n} aġent","people.working.html.one":"⚡ {n} qed jaħdem bħalissa","people.working.html.other":"⚡ {n} qed jaħdmu bħalissa","pre.title":"AI-gile: qed tinbena xi ħaġa","pre.description":"Hawn qed tinbena xi ħaġa: bord fejn timijiet tal-AI jibnu dak li titlob, u jgħallmuk waqt li jaħdmu. Għalissa pre-alpha magħluqa mal-ħbieb.","pre.h1":"Hawn qed tinbena xi ħaġa. 🤫","pre.line":"Bord fejn timijiet tal-AI jibnu dak li titlob, u jgħallmuk waqt li jaħdmu. Għalissa pre-alpha magħluqa mal-ħbieb.","pre.btn":"🔔 Għarrafni meta tiftaħ","pre.peek":"Wara l-ħġieġ: il-bord veru, live. Kull karta hija strixxa kkulurita.","pre.peekFake":"Wara l-ħġieġ: hekk jidher bord fuq ix-xogħol.","pre.night":"🌙 Il-għassa tal-lejl qed imexxi · 😴 il-bniedem qed jistrieħ","features.aria":"X'jagħmel","f.pile.h":"Munzell wieħed għalik","f.pile.html":"<b>Għalik</b> iżomm kollox li qed jistenniek, fil-proġetti kollha: mistoqsijiet, affarijiet biex tittestja, kompiti li bniedem biss jista' jagħmel. Il-kju tiegħek jgħid x'inhu li jmiss u kemm se jieħu.","f.sleep.h":"Timijiet li jaħdmu waqt li torqod","f.sleep.p":"Kull proġett għandu lead u tim ta' aġenti tal-AI. Ikkumenta fuq karta u t-tim iqum, jagħmel ix-xogħol, u jirritornaha lura b'passi li bniedem għajjien jista' jsegwi.","f.tester.h":"Tester tal-AI jiċċekkja l-ewwel","f.tester.p":"Qabel ma xi ħaġa tasal għandek, tester isegwi l-passi f'kopja tal-app u juri x'ra, b'screenshot. Għaddi minn dawk li għaddew u aċċetta b'klikk wieħed.","f.proof.h":"Provi, mhux wegħdiet","f.proof.p":"Kull konsenja turi x'inbidel: il-fajls, id-diff, l-iscreenshots. M'għandekx bżonn tiftaħ kull app biex tara jekk huwiex lest.","f.chat.h":"Iddiskuti mal-leads tiegħek","f.chat.p":"Strixxa bi stil ta' Discord: ikona waħda għal kull proġett, djamanti vjola għal dak li jeħtieġek. Ibgħat idea lil lead; jagħmilha karti u pjan, b'buttuna ✅ Go.","f.tidy.h":"Iżomm lilu nnifsu f'ordni","f.tidy.p":"Karti relatati jingħaqdu f'waħda, titli mħawdin jissewwew, u kontroll tat-tokens iżomm il-kodiċi irqiq. Inqas affarijiet biex taqleb bejniethom, inqas biex taħseb fihom.","f.private.h":"Tiegħek, fuq il-kompjuter tiegħek","f.private.li1":"Il-bord jaħdem fuq il-magna tiegħek stess u jwieġeb lilek biss.","f.private.li2":"Il-messaġġi privati bejn in-nies huma ċifrati end-to-end.","f.private.li3":"L-ebda kont, l-ebda trackers, l-ebda cookies.","f.lang.h":"Bil-lingwa tiegħek","f.lang.p":"Aktar minn 120 lingwa, mill-Malti, il-Welsh u l-Ġappuniż sal-pirata, Yoda u l-Klingon, b'qlib mgħaġġel lura għall-Ingliż għat-termini tekniċi.","f.service.h":"Minn idea għal servizz veru","f.service.p":"Bnejt xi ħaġa bl-AI li issa n-nies qed jużawha? Immarkaha bħala servizz u l-bord jgħinek tmexxiha sew: uptime checks, paġna tal-istatus pubblika, inċidenti b'rapport, bidliet li jeħtieġu Go, backups iċċekkjati kuljum. L-Għajnuna tgħallmek kull pass hekk kif timxi.","msgr.h2":"AI-gile Messenger: it-tim tiegħek fil-but","msgr.p1":"Kellem lit-tim tal-AI tiegħek mingħajr ma tiftaħ il-bord. Iċċettja mal-mexxejja tal-proġetti u mal-ħbieb tiegħek, ara l-passi tat-test ta' karta u wieġeb għalihom, kollox mit-telefon tiegħek.","msgr.p2":"Biex tqabbdu, skennja kodiċi QR fuq il-bord tiegħek. L-ewwel darba? Chat demo ħbiberija turik kollox.","msgr.when":"L-ewwel Android, imbagħad verżjoni web għat-telefowns u għall-iPhone.","msgr.who":"Il-mexxej tal-proġett tiegħek","msgr.b1":"It-tiswija tal-modalità skura lesta. Trid il-passi tat-test?","msgr.b2":"Iva, jekk jogħġbok!","msgr.b3":"1. Iftaħ l-Issettjar. 2. Agħżel Skur. Jidher sew?","tl.aria":"Skeda taż-żmien mill-ewwel konversazzjoni sal-pjan","tl.h2":"Mill-ewwel chat sa dak li jmiss","tl.lede":"Dati u ħinijiet reali, fiż-żona tal-ħin tiegħek. Wara llum huwa l-pjan, mingħajr dati mwiegħda.","tl.today":"Illum","tl.planned":"ippjanat","tl.doing":"għaddej","tl.cards.one":"{n} karta","tl.cards.other":"{n} karta","join.h2":"Ingħaqad magħna","join.lede":"AI-gile qed jinbena minn wieħed stramb b'daqna, b'AuDHD u xi battalji mas-saħħa mentali, u numru kbir ta' aġenti paċenzjużi. Għalissa huwa privat, alpha magħluqa ma' ħbieb. Trid tipprova meta jinfetaħ?","join.btn":"Irreġistra l-interess","join.small":"Se nibagħtulek email, xejn aktar","footer.tag":"AI-gile. L-ebda trackers, l-ebda cookies, l-ebda kafè għall-istand-up.","footer.licence":"Liċenzja tan-negozju","footer.status":"Status","footer.privacy":"X'inżommu","footer.thanks":"Sejħiet grazzi għal ChilledChat","form.sending":"Qed jintbagħat…","form.failed":"Dak ma ħadimx: erġa' pprova aktar tard.","form.offline":"Ma setgħetx tintlaħaq AI-gile: erġa' pprova aktar tard.","form.keep":"Nużaw dan biss biex inwieġbuk, imbagħad inħassruh. L-ebda trackers, l-ebda cookies.","form.keepLink":"X'inżommu","interest.title":"AI-gile: għarrafni meta tiftaħ l-alpha","interest.description":"Ħalli l-email tiegħek biex tisma' meta tinfetaħ l-alpha jew il-beta magħluqa ta' AI-gile.","interest.h1":"🔔 Għarrafni meta tiftaħ","interest.lede":"AI-gile qiegħed f'pre-alpha magħluqa. Ħalli l-email tiegħek u niktbulek darba, meta jkun hemm post għalik.","interest.email":"L-email tiegħek","interest.which":"Liema test?","interest.alpha":"Alpha magħluqa: bikrija, mhux rfinuta, ħafna bidliet","interest.beta":"Beta: aktar stabbli, aktar tard","interest.both":"Kwalunkwe, dik li tiġi l-ewwel","interest.submit":"Poġġini fuq il-lista","interest.thanks":"Grazzi! Int fuq il-lista.","licence.title":"AI-gile: liċenzja tan-negozju","licence.description":"Qed tuża AI-gile fin-negozju tiegħek? Applika għal liċenzja tan-negozju b'xejn.","licence.h1":"📜 Liċenzja tan-negozju","licence.lede":"Qed tuża AI-gile x-xogħol? Għidilna min int u x'tagħmel. Jekk jagħmel xi ġid, il-liċenzja hija b'xejn.","licence.company":"Kumpanija","licence.website":"Websajt","licence.what":"X'tagħmel","licence.how":"Kif jgħin id-dinja","licence.email":"Email","licence.submit":"Applika","licence.thanks":"Grazzi! Nirrispondulek bl-email.","status.title":"Status ta' AI-gile","status.h1":"Status ta' AI-gile","status.quiet":"Kollox kwiet","status.intro":"AI-gile qed jaħdem bħalissa? Din il-paġna tiċċekkja s-sit, il-qsim tal-bordijiet, is-sejħiet u t-tniżżil kull 5 minuti.","status.up":"Qed jaħdem (wieġeb f'{ms} ms)","status.slow":"Ma weġibx għall-aħħar ċekk, qed nerġgħu nippruvaw","status.down":"Waqaf: ma weġibx għall-aħħar żewġ ċekkijiet","status.svc.web":"Sit web","status.svc.web.offers":"Dan is-sit: x'inhu AI-gile, u l-formola tal-interess","status.svc.boards":"Qsim tal-bordijiet","status.svc.boards.offers":"Bordijiet pubbliċi, messaġġi bejn il-ħbieb u stediniet","status.svc.calls":"Sejħiet","status.svc.calls.offers":"Vuċi, vidjo u qsim tal-iskrin f'AI-gile","status.svc.download":"Tniżżil","status.svc.download.offers":"L-installatur għal Windows u l-links tal-istediniet","status.checking":"Qed jiċċekkja…","status.offline":"Is-servizz tal-istatus ma jistax jintlaħaq bħalissa (qed nerġgħu nippruvaw)","status.updated":"aġġornat {ago}","status.justNow":"għadu kif","status.min":"{n} min ilu","status.hours":"{n} sieg ilu","status.days":"{n} j ilu","privacy.title":"AI-gile: x'inżommu","privacy.h1":"X'inżommu","privacy.lede":"Fil-qosor: biss dak li tibgħatilna, u mhux għal żmien twil.","privacy.only":"Biss dak li tibgħatilna: dak li tikteb f'formola, bħall-email tiegħek. Xejn iktar dwarek.","privacy.sealed":"Jiġi ssiġillat biex is-server tagħna ma jkunx jista' jaqrah: fil-browser tiegħek qabel ma jitlaq (fuq browser eqdem, hekk kif jasal). Il-bord tagħna biss jista' jiftħu.","privacy.server":"Jitħassar mis-server hekk kif jasal fuq il-bord tagħna. Kull ma jibqa' hemm wara 30 jum jitħassar xorta waħda.","privacy.board":"Inżommuh fuq il-bord tagħna biss sakemm inwieġbuk, imbagħad inħassruh minn hemm ukoll.","privacy.none":"L-ebda trackers, l-ebda cookies, l-ebda analitika.","privacy.local":"Il-lingwa tiegħek u l-għażla bejn tema ċara jew skura jibqgħu fil-browser tiegħek. Qatt ma jintbagħtulna.","privacy.ask":"Trid li jitħassar qabel? Wieġeb l-email tagħna u għidilna.","live.h2":"Ara kif qed jinbena, live","live.caption":"Kull karta hija moħbija: tara l-forma tax-xogħol, mhux il-kliem.","live.watching.one":"live: {n} qed josservaw","live.watching.other":"live: {n} qed josservaw","live.last.now":"L-aħħar karta tmexxiet ftit ilu","live.last.min.one":"L-aħħar karta tmexxiet {n} minuta ilu","live.last.min.other":"L-aħħar karta tmexxiet {n} minuti ilu","live.last.hour.one":"L-aħħar karta tmexxiet {n} siegħa ilu","live.last.hour.other":"L-aħħar karta tmexxiet {n} sigħat ilu","live.last.day.one":"L-aħħar karta tmexxiet {n} jum ilu","live.last.day.other":"L-aħħar karta tmexxiet {n} jiem ilu","live.offline":"Il-bord live qed jieħu nifs. Erġa' ejja dalwaqt.","live.cols":"Backlog|Biex isir|Għaddej|It-tim qed jivverifika|Għalik biex tittestja|Għat-tim|Lest","pitch.words.few":"{n} kelmiet","pitch.words.many":"{n} kelma","pitch.letters.few":"{n} ittri","pitch.letters.many":"{n} ittra","pitch.chars.few":"{n} karattri","pitch.chars.many":"{n} karattru","count.line.html.few":"{n} karti fuq il-bord bħalissa","count.line.html.many":"{n} karta fuq il-bord bħalissa","tl.cards.few":"{n} karti","tl.cards.many":"{n} karta"},"lines":{"unit":"words","sizes":[{"n":1,"texts":["Kanban.","Robots.","Iddelegat."]},{"n":2,"texts":["Robots jaħdmu.","Aġenti, f'ordni.","Ideat, mibnija."]},{"n":3,"texts":["Kanban għar-robots.","Ideat isiru funzjonijiet.","B'xejn, lokali, ittestjat."]},{"n":5,"texts":["Bord kanban fejn jibnu l-aġenti.","Inti tikteb karti. Aġenti jibnu.","B'xejn, lokali, ittestjat, ftit iblah."]},{"n":8,"texts":["Bord kanban b'xejn fejn jaħdmu l-aġenti tal-AI.","Ikteb idea waħda. L-aġenti jibnuha. Inti taċċettaha.","Agile għal bniedem wieħed u ħafna robots paċenzjużi."]},{"n":13,"texts":["Bord kanban fuq il-kompjuter tiegħek fejn l-aġenti tal-AI jieħdu l-karti.","Ikteb idea. Tim sħiħ ta' aġenti jibnuha. Wara tester jiċċekkjaha sew għalik.","B'xejn, mingħajr kontijiet jew trackers: bord, ftit robots, u inti fil-kontroll."]},{"n":21,"texts":["AI-gile huwa bord kanban biex taħdem ma' aġenti tal-kodiċi bl-AI. Huma jieħdu l-karti kollha; inti tittestjahom u taċċettahom.","Kull proġett għandu lead u tim ta' aġenti tal-AI. Ikkumenta fuq kwalunkwe karta u t-tim jibda jaħdem.","Bord personali tal-affarijiet li jridu jsiru, b'xejn, li jaħdem fuq il-kompjuter tiegħek. Dawk li jaħdmu huma robots. Dak li jgħid iva int."]},{"n":34,"texts":["Inti tpoġġi l-ideat tiegħek fuq bord. Tim ta' aġenti tal-AI jibdilhom f'funzjonijiet li jaħdmu, jittestjahom, u jirritornawhom b'passi biex tipprova. Xejn ma jgħodd bħala lest sakemm int ma tgħidx hekk.","AI-gile huwa bord kanban magħmul id-dar li Rich bena b'ħafna għajnuna mill-aġenti li issa jmexxi. Huwa b'xejn, jaħdem fuq il-kompjuter tiegħek, u jinqasam ma' ħbieb, mhux jinbigħ.","Immaġina bord kanban tas-soltu, b'kolonni minn Backlog sa Lest, ħlief li l-karti jittieħdu mill-aġenti tal-AI. Jirrappurtaw il-progress, jistaqsu meta jibqgħu mwaħħla, u dejjem jistennew l-approvazzjoni tiegħek qabel ma jmorru 'l quddiem."]},{"n":55,"texts":["AI-gile huwa bord kanban fejn it-tim huwa magħmul minn aġenti tal-AI. Kull proġett għandu lead li jippjana x-xogħol u ħaddiema li jibnuh. Meta funzjoni tkun lesta, tester tal-AI jipprovaha u jieħu screenshot, imbagħad tasal fuq il-munzell tiegħek. Aċċettaha, jew ikkumenta u jerġgħu jaħdmu fuqha.","Beda bħala mod ta' persuna waħda biex iżomm rendikont ta' ħafna sessjonijiet tal-kodiċi bl-AI f'daqqa, u kiber f'bord veru. Jaħdem fuq il-magna tiegħek, ma jeħtieġ l-ebda kont u m'għandu l-ebda trackers. Huwa b'xejn għall-ħbieb u għal min hu kurjuż. Għadu wkoll mhux lest, għalhekk stenna xi truf mhux irfinati u sorpriża minn żmien għal żmien.","Din hija l-verżjoni onesta tal-istorja kollha. Xorta trid ikollok l-ideat, u xorta trid tiċċekkja r-riżultati. Dak li jagħmel AI-gile huwa dak kollu li hemm bejniethom: iżomm il-karti f'ordni, iqajjem l-aġent t-tajjeb meta tikkumenta, juri eżattament x'inbidel, u jżomm kollox f'munzell qasir wieħed biss għalik, mingħajr storbju."]},{"n":89,"texts":["AI-gile huwa bord kanban kompletament b'xejn li tmexxi fuq il-kompjuter tiegħek stess. Minflok in-nies, kull proġett għandu tim sħiħ ta' aġenti tal-AI: lead li jibdel l-ideat tiegħek f'karti u pjan, u għajnuna li tieħu l-karti skont il-prijorità. Meta xi ħaġa tinbena, tester tal-AI isegwi l-passi tat-test u juri lilek x'ra, b'screenshot. Imbagħad tistenna f'munzell wieħed biss jismu Għalik. Inti taċċettaha, jew tikkumenta u t-tim jerġa' jipprova mill-ġdid. Xejn ma jasal qatt f'Lest mingħajrek.","Ftit karatteristiċi li forsi ma tistennihomx. Għassa tal-lejl iżżomm il-kolonna Biex isir mimlija waqt li torqod, billi tagħżel karti li ma jeħtieġux tweġiba minnek. Għadd tat-tokens juri kemm użaw l-aġenti llum u din il-ġimgħa, u l-Mod bla Tokens jgħidilhom jieqfu jonfqu. Tista' tibgħat messaġġi lill-ħbieb, u l-messaġġi privati huma ċifrati end-to-end. Il-bord jitkellem madwar 120 lingwa, fosthom il-Malti, il-pirata u l-Klingon. Xejn minn dan ma jiswa xejn, u ħadd ma qed jipprova jbigħhulek.","AI-gile huwa proġett żgħir u personali, mhux kumpanija. Rich xtaq jieħu ħsieb diversi proġetti tal-kodiċi bl-AI mingħajr ma jiftaħ kull app biex jiċċekkjahom, allura hu u l-aġenti bnew bord għal dan, u mbagħad użaw il-bord biex jibnu l-bqija tiegħu nnifsu. Qiegħed f'pre-alpha magħluqa, li jfisser li jaħdem, il-biċċa l-kbira, għal ftit ħbieb. M'hemm l-ebda paġna tal-prezzijiet, l-ebda newsletter u l-ebda pjan ta' tkabbir. Jekk jidher utli, tista' titlob biex tipprovah meta jinfetaħ ftit aktar."]},{"n":144,"texts":["AI-gile huwa bord kanban għal bniedem wieħed u ħafna aġenti tal-AI paċenzjużi. Jaħdem fuq il-kompjuter tiegħek stess u huwa għal kollox b'xejn. Inti żżid proġetti, u kull proġett jaqla' lead u tim żgħir. Tiddiskuti mal-lead, kemmxejn bħal fuq Discord, u tiddeskrivi idea; il-lead jagħmilha karti u pjan, u jistenna li tagħfas Go. It-tim jaħdem mal-karti skont il-prijorità, b'għodda sempliċi tal-linja tal-kmandi magħmula għall-mudelli tal-lingwa. Qabel ma xi ħaġa tirritorna għandek, tester tal-AI isegwi l-passi f'kopja tal-app u jwaħħal screenshot. Ix-xogħol lest jasal fuq il-munzell tiegħek, mal-fajls li nbidlu, id-diff u l-iscreenshots. Inti taċċettah, jew tħalli kumment u t-tim iqum u jerġa' jipprova. Kull ma jsir jidher fuq il-bord, f'kolonni mill-Backlog sa Lest. Ma jeħtieġ l-ebda kont. Int biss tista' tmexxi karta għal Lest.","Jum ma' AI-gile, bejn wieħed u ieħor. Filgħaxija tħalli ftit kummenti: din il-buttuna hi fil-post ħażin, dik il-lista għandha tinżamm ordnata, nistgħu nkollhom mod skur. Tmur torqod. L-aġenti jaqraw il-kummenti, jagħmlu l-bidliet, jittestjawhom u jirritornawhom lilek. Jekk Biex isir jispiċċa, l-għassa tal-lejl timlieh mill-backlog b'karti li ma jeħtieġu l-ebda tweġiba minnek. Filgħodu hemm munzell qasir wieħed: par ta' mistoqsijiet u ftit affarijiet biex tipprova, kull wieħed b'passi li persuna ngħasana tista' ssegwi u screenshot ta' kif jaħdem. Tikklikkja minnu, taċċetta t-tajba u tibgħat lura l-bqija. Għadd tat-tokens juri kemm intuża dan kollu, u l-Mod bla Tokens hemm għal ġimgħat irqaq. Jekk xi ħaġa ma tkunx ċara, it-tim jistaqsi qabel ma jmur 'il quddiem. Imbagħad tieħu l-kolazzjon, li l-aġenti għadhom ma jistgħux jgħinu fih.","L-ewwel, x'mhuwiex AI-gile. Mhuwiex startup, mhuwiex għall-bejgħ, u ħadd ma qed jiġbor id-dejta tiegħek. Huwa bord b'xejn li jaħdem fuq il-kompjuter tiegħek, mingħajr kontijiet, trackers jew cookies. X'inhu: post wieħed irranġat biex tara l-proġetti kollha tiegħek tal-kodiċi bl-AI f'daqqa, b'tim ta' aġenti jagħmlu l-karti u inti tieħu d-deċiżjonijiet. Jingħaqad karti relatati, isewwi titli mħawdin, u josserva kemm il-kodiċi jibqa' irqiq. Jitkellem madwar 120 lingwa, mill-Malti sal-pirata u l-Klingon. Il-ħbieb jistgħu jibagħtu messaġġi lil xulxin, privatament u ċifrati. Inbena minn Rich u numru kbir ta' aġenti paċenzjużi, li l-aktar użawh huma stess. Ma jbigħ xejn, ma jitlob xejn, u ma jgħaddi xejn lil ħadd. Qiegħed f'pre-alpha magħluqa, għalhekk f'xi postijiet għadu mhux rfinut. Jekk jidher divertenti, itlob b'ġentilezza u forsi tidħol kmieni."]}],"quips":{"1":"Kelma waħda. Kuraġġuża. Forsi kuraġġuża żżejjed.","3":"Tliet kelmiet. Diġà aktar onesti mill-biċċa l-kbira tal-paġni tal-prodotti.","8":"Tmien kelmiet. Għadu iqsar minn stand-up.","21":"It-tulijiet huma story points, mill-mod. Naturalment.","55":"Ħamsa u ħamsin kelma. Żewġ karti ntemmu waqt li qrajt dan.","144":"Din kienet it-tawwala. M'hemm l-ebda 233. L-aġenti marru jorqdu."}},"timeline":{"first-idea.name":"L-ewwel idea","first-idea.line":"L-ewwel konversazzjoni ta' kollox, qabel ma kien jeżisti kodiċi.","first-board.name":"L-ewwel bord","first-board.line":"Bord li jżomm rendikont tal-bini tiegħu stess: karti, kolonni, ġbid u ċaqliq, proġetti.","team-roles.name":"Tim u rwoli","team-roles.line":"Profili tal-aġenti, mudelli tat-timijiet, spazji u min jagħmel xiex.","install.name":"Installazzjoni u rilaxxi","install.line":"Zip li ħabib jista' jinstalla, aġġornamenti awtomatiċi, kanali u rollback.","usage-saver.name":"Tfaddil tal-użu","usage-saver.line":"Kejl ta' kemm jiswew it-tħaddim, kodiċi irqiq, u l-limitu tiegħek jitfaddal.","friends.name":"Ħbieb u qsim","friends.line":"DMs privati, relay imħawwad, stediniet, rwoli u proġetti maqsuma.","languages.name":"Lingwi","languages.line":"Kull test tal-iskrin f'fajl tal-lingwa, bl-Olandiż u l-Fjamming l-ewwel.","ai-tester.name":"Tester tal-AI","ai-tester.line":"Tester jiċċekkja kull konsenja l-ewwel u juri x'ra.","website.name":"Is-sit","website.line":"aigile.lol, it-teaser u din l-iskeda taż-żmien.","streaming.name":"Chat u streaming","streaming.line":"Discord, Twitch, OBS, mod tal-istreamer, GIFs u emojis.","no-ai.name":"Edizzjoni bla AI","no-ai.line":"Bord għal nies li jikkodifikaw mingħajr AI, u bordijiet pubbliċi.","night-watch.name":"Għassa tal-lejl","night-watch.line":"Għassies u Scrum Master iżommu t-timijiet fuq il-binarju waqt li torqod.","p-more.name":"Kull ħaġa oħra","p-more.line":"Ideat iżgħar li għadhom jistennew id-dawra tagħhom.","p-android.name":"Telefon u Android","p-android.line":"Dħul fil-bord tiegħek mit-telefon, imbagħad app nattiva għall-Android.","p-release.name":"Alpha u aktar 'il quddiem","p-release.line":"Alpha magħluqa, is-sit live, imbagħad il-beta.","p-languages.name":"Aktar lingwi","p-languages.line":"130 lingwa, u mod ta' immersjoni għal min qed jitgħallem.","p-engines.name":"Aktar magni tal-AI","p-engines.line":"Agħżel Claude, Codex, Gemini, Copilot jew Cursor għal kull aġent.","p-pro.name":"Prattika professjonali","p-pro.line":"Tikketti tar-riskju, bibien tal-merge, karti tal-inċidenti u ħitan tal-ħarsien.","p-self.name":"Ngħożżuk","p-self.line":"Mod għajjien, tfakkiriet ta' kura personali u 4:20.","p-servers.name":"Servers u skala","p-servers.line":"Settings globali tas-server, rwoli u ppjanar għat-tkabbir.","p-livestream.name":"Żidiet għall-istreaming","p-livestream.line":"Chat ta' Twitch, emojis personalizzati u veduta live pubblika."},"words":{"button":"📖 Termini tekniċi","h":"📖 Kliem spjegat","intro":"Il-kliem li ssib f'AI-gile, b'lingwa sempliċi: kif tibnih, kif tibdlu bla periklu, kif iżżommu jaħdem għan-nies li jużawh, u kif taħdem bħala tim mal-AI.","search":"Fittex kelma…","none":"Ebda kelma ma taqbel ma' dak.","close":"Agħlaq","count":{"one":"{count} kelma","other":"Kliem: {count}"},"groups":[{"id":"idea","name":"💡 Idea and discovery"},{"id":"plan","name":"🗺️ Planning the work"},{"id":"agile","name":"🔁 Agile ways of working"},{"id":"build","name":"🛠️ Il-bini"},{"id":"test","name":"🧪 Testing and quality"},{"id":"change","name":"🔀 Bidla bla periklu"},{"id":"run","name":"🛎️ It-tmexxija ta' servizz"},{"id":"sec","name":"🔒 Security and privacy"},{"id":"ai","name":"🤖 Working with AI"},{"id":"money","name":"💰 Money and licences"}],"list":[{"id":"discovery","g":"idea","word":"Discovery","text":"The early stage of finding out which problem is worth solving and for whom, before anything gets built.","also":["discovery phase"]},{"id":"problemstmt","g":"idea","word":"Problem statement","text":"One or two sentences saying who has a problem, what it is and why it matters, so everyone aims at the same thing.","also":["problem statements"]},{"id":"user","g":"idea","word":"User","text":"A person who uses what you build. Their needs are what the work is for.","also":["users"],"noTip":1},{"id":"stakeholder","g":"idea","word":"Stakeholder","text":"Anyone who cares how the work turns out or is affected by it, like the people paying for it, using it or supporting it.","also":["stakeholders"]},{"id":"persona","g":"idea","word":"Persona","text":"A made-up but realistic person who stands for one kind of user, so the team can ask “would Sam find this easy?”","also":["personas"]},{"id":"userresearch","g":"idea","word":"User research","text":"Talking to and watching real people to learn what they need, rather than guessing.","also":["user interviews"]},{"id":"journey","g":"idea","word":"User journey","text":"The steps a person takes to get something done, from first hearing about it to finishing, also outside your product. Drawing it out shows where they get stuck.","also":["user journeys","customer journey"]},{"id":"painpoint","g":"idea","word":"Pain point","text":"Something that annoys or slows people down today. Good products take pain points away.","also":["pain points"]},{"id":"assumption","g":"idea","word":"Assumption","text":"Something you believe but haven’t checked yet. Writing assumptions down shows what to test first.","also":["assumptions"],"noTip":1},{"id":"hypothesis","g":"idea","word":"Hypothesis","text":"A best guess you plan to check, with what you expect to happen, like “people will sign up if the first month is free”.","also":["hypotheses"]},{"id":"experiment","g":"idea","word":"Experiment","text":"A small planned test to learn whether an idea works, before betting a lot on it.","also":["experiments"],"noTip":1},{"id":"poc","g":"idea","word":"Proof of concept (PoC)","text":"A quick rough try to see if an idea can work at all. It is usually thrown away once you have the answer.","also":["PoC","proof of concept"]},{"id":"prototype","g":"idea","word":"Prototype","text":"An early model of the product, often clickable pictures, to try the idea on people before building it properly.","also":["prototypes"]},{"id":"wireframe","g":"idea","word":"Wireframe","text":"A simple sketch of a screen showing where things go, without colours or real content.","also":["wireframes"]},{"id":"mockup","g":"idea","word":"Mockup","text":"A detailed picture of how a screen will look, with real colours and text, but nothing works yet.","also":["mockups","mock-up","mock-ups"]},{"id":"bizcase","g":"idea","word":"Business case","text":"The reasons for doing a project: what it costs, what it brings in or saves, and the risks.","also":["business cases"]},{"id":"feasibility","g":"idea","word":"Feasibility","text":"Whether something can really be built and looked after with the time, money and skills you have."},{"id":"outcome","g":"idea","word":"Outcome","text":"The change you want for people, like fewer missed appointments. It matters more than how much you build.","also":["outcomes"],"noTip":1},{"id":"output","g":"idea","word":"Output","text":"Something the team makes, like a new screen or a report. Making it doesn’t automatically mean it helps anyone.","also":["outputs"],"noTip":1},{"id":"successmetric","g":"idea","word":"Success metric","text":"A number that tells you whether the work did what it was for, like more people finishing their order.","also":["success metrics"]},{"id":"kpi","g":"idea","word":"Key performance indicator (KPI)","text":"An important number you watch to see if things are going well, like sign-ups per week.","also":["KPI","KPIs","key performance indicator"]},{"id":"okr","g":"idea","word":"Objectives and key results (OKRs)","text":"A way of setting goals: the objective says what you want, and a few key results are the numbers that show you got there.","also":["OKR","OKRs"]},{"id":"product","g":"plan","word":"Product","text":"The thing being built and looked after for its users, such as an app, a website or a tool.","also":["products"],"noTip":1},{"id":"vision","g":"plan","word":"Product vision","text":"A short statement of who the product helps and where it is heading in the long run.","also":["vision statement"]},{"id":"po","g":"plan","word":"Product owner (PO)","text":"The person who decides what gets built and in what order, so the team always works on what matters most. In AI-gile that is you.","also":["PO","product owners"]},{"id":"pm","g":"plan","word":"Product manager (PM)","text":"The person who looks after a product’s direction: which problems it solves, for whom and why. PM can also mean project manager, so check which.","also":["product managers"]},{"id":"projmgr","g":"plan","word":"Project manager","text":"The person who keeps a project on time and on budget, tracking who does what and by when.","also":["project managers"]},{"id":"roadmap","g":"plan","word":"Roadmap","text":"A rough plan of what is coming over the next months, in order. It shows direction, not exact dates, and changes as you learn.","also":["roadmaps"]},{"id":"milestone","g":"plan","word":"Milestone","text":"A point in a project worth marking, like “first version live” or “100 users”.","also":["milestones"]},{"id":"mvp","g":"plan","word":"Minimum viable product (MVP)","text":"The smallest version of a product that is still useful to real people, so you can learn from them early.","also":["MVP","MVPs","minimum viable product"]},{"id":"requirement","g":"plan","word":"Requirement","text":"Something the finished product must do or be.","also":["requirements"],"noTip":1},{"id":"scope","g":"plan","word":"Scope","text":"What is included in the work and, just as important, what is not.","also":["in scope","out of scope"]},{"id":"scopecreep","g":"plan","word":"Scope creep","text":"When more and more gets added to the work bit by bit, without anyone agreeing on the extra time or cost, so it never quite finishes.","also":["feature creep"]},{"id":"feature","g":"plan","word":"Feature","text":"One thing the product can do for people, like “reset your password”.","also":["features"],"noTip":1},{"id":"epic","g":"plan","word":"Epic","text":"A big piece of work, too large for one go, so it is split into smaller cards.","also":["epics"]},{"id":"story","g":"plan","word":"User story","text":"A small piece of work written from the user’s side: “As a shopper, I want to save my basket, so I can finish later.” It starts a conversation about what to build.","also":["user stories"]},{"id":"ac","g":"plan","word":"Acceptance criteria (AC)","text":"The checks one card must pass to count as done, agreed before work starts, like “the basket is still there after I log out and back in”.","also":["acceptance criteria"]},{"id":"task","g":"plan","word":"Task","text":"A single job to be done, often one small step of a bigger story.","also":["tasks"],"noTip":1},{"id":"ticket","g":"plan","word":"Ticket","text":"Another word for a card: one piece of work or one request, tracked from start to finish.","also":["tickets"]},{"id":"priority","g":"plan","word":"Priority","text":"How important or urgent something is compared with everything else, so the most important work goes first.","also":["priorities"],"noTip":1},{"id":"prioritise","g":"plan","word":"Prioritisation","text":"Putting work in order of importance. A common way is MoSCoW: Must have, Should have, Could have, Won’t have this time.","also":["MoSCoW"]},{"id":"estimate","g":"plan","word":"Estimate","text":"A best guess at how big or how long a piece of work is. It is a guess, not a promise.","also":["estimates","estimation"],"noTip":1},{"id":"storypoints","g":"plan","word":"Story points","text":"A way of guessing the size of work by comparing cards with each other (“about twice as big as that one”) rather than in hours. They aren’t for comparing teams.","also":["story point"]},{"id":"tshirt","g":"plan","word":"T-shirt sizing","text":"Guessing the size of work as S, M, L or XL. Quick and good enough for early planning.","also":["t-shirt sizes"]},{"id":"poker","g":"plan","word":"Planning poker","text":"A game for estimating: everyone shows a size card at the same time, then the highest and lowest explain why.","also":["Scrum poker"]},{"id":"dependency","g":"plan","word":"Dependency","text":"When one piece of work can’t start or finish until another one does.","also":["dependencies"]},{"id":"blocker","g":"plan","word":"Blocker","text":"Anything stopping work from moving forward right now, like a missing answer or a broken tool.","also":["blockers"]},{"id":"deadline","g":"plan","word":"Deadline","text":"The date something must be finished by.","also":["deadlines"],"noTip":1},{"id":"deliverable","g":"plan","word":"Deliverable","text":"Something concrete the work produces and hands over, like a working page or a report.","also":["deliverables"]},{"id":"forecast","g":"plan","word":"Forecast","text":"A prediction of what is likely to happen, like when the work will be done, based on what you know so far.","also":["forecasts"],"noTip":1},{"id":"metric","g":"plan","word":"Metric","text":"Anything you measure and track over time, like page visits or how long a fix takes.","also":["metrics"]},{"id":"feedback","g":"plan","word":"Feedback","text":"What people tell you about your work, good and bad. Getting it early and often is the heart of Agile.","noTip":1},{"id":"backlog","g":"agile","word":"Backlog","text":"Ideat u xogħol li għadu mhux ippjanat. Xejn hemmhekk ma jitħadem sakemm ma jmurx għal Biex isir."},{"id":"sprint","g":"agile","word":"Sprint","text":"Perjodu qasir ta' xogħol (spiss ġimgħa jew tnejn) b'sett ta' karti miftiehem biex jitlestew.","also":["sprints"]},{"id":"standup","g":"agile","word":"Stand-up","text":"Check-in rapidu: x'għamel kull membru tat-tim, x'se jagħmel wara, u x'qed iwaqqfu.","also":["standup","stand-ups"]},{"id":"kanban","g":"agile","word":"Kanban","text":"Bord b'kolonni (Biex isir, Għaddej, Lest) fejn il-karti jimxu mix-xellug lejn il-lemin hekk kif isir ix-xogħol."},{"id":"wip","g":"agile","word":"WIP limit","text":"Work in progress: l-aktar karti li kolonna għandha żżomm, biex it-tim itemm l-affarijiet qabel jibda aktar.","also":["WIP"]},{"id":"dod","g":"agile","word":"Definizzjoni ta' Magħmul","text":"Il-checklist qasira tat-tim ta' xi jfisser “magħmul”, bħal ittestjat u spjegat, qabel ma kard tingħatalek. It-tewmija tagħha, id-Definizzjoni ta' Lest biex jibda, tgħid meta kard tkun ċara biżżejjed biex tibda.","also":["Definizzjoni ta' Lest biex jibda","Definition of Done","Definition of Ready"]},{"id":"retro","g":"agile","word":"Retro","text":"Ħarsa lura lejn kif jaħdem it-tim, biex taqblu fuq ħaġa waħda li tagħmlu aħjar. F'AI-gile retro tissuġġerixxi bidla fil-mod kif jaħdem it-tim, u int tgħid Go jew Mhux issa.","also":["retros","retrospettiva","retrospettivi"]},{"id":"swarm","g":"agile","word":"Swarm","text":"Kulħadd fuq il-gverta: kull tim iħalli xogħol ieħor biex jgħin fuq proġett urġenti wieħed sakemm jissolva. Proġetti oħra jistennew sadanittant.","also":["swarming"]},{"id":"scrummaster","g":"agile","word":"Scrum Master","text":"Dak li jżomm ix-xogħol għaddej: jinnota kards imwaħħlin, iqanqal lit-timijiet u jfakkrek f'dak li qed jistenna. F'AI-gile l-Lead Scrum Master jagħmel dan f'kull proġett.","also":["Lead Scrum Master"]},{"id":"agile","g":"agile","word":"Agile","text":"A way of working in small steps: build a little, show real results often, learn from what people say and change the plan as you go, instead of planning everything up front.","also":["Agile development","agile ways of working"]},{"id":"manifesto","g":"agile","word":"Agile Manifesto","text":"A short statement written in 2001 by software makers. It puts people, working results, close work with customers and responding to change ahead of heavy plans and paperwork.","also":["Manifesto for Agile Software Development"]},{"id":"waterfall","g":"agile","word":"Waterfall","text":"The older way of working: plan everything, then build it all, then test it all, one stage after another. Changes late on are hard and costly.","also":["waterfall model"]},{"id":"iteration","g":"agile","word":"Iteration","text":"One round of building something, checking it and improving it. Agile work is a chain of these, and a sprint is one kind.","also":["iterations"]},{"id":"increment","g":"agile","word":"Increment","text":"A new working piece added to the product in a sprint or round of work, which fits with what was already there.","also":["increments"]},{"id":"scrum","g":"agile","word":"Scrum","text":"A popular Agile way of working: a small team works in short sprints towards a goal, with set roles and a few regular meetings to plan, check and improve."},{"id":"scrumteam","g":"agile","word":"Scrum team","text":"The small group that does the work in Scrum: a product owner, a Scrum Master and the developers.","also":["Scrum teams"]},{"id":"ceremonies","g":"agile","word":"Scrum events","text":"The regular meetings in Scrum: sprint planning, the daily scrum, the sprint review and the retro. Many people call them ceremonies.","also":["ceremonies","Scrum ceremonies"]},{"id":"sprintplan","g":"agile","word":"Sprint planning","text":"The meeting at the start of a sprint where the team agrees why the sprint matters, which cards to take on and how to start.","also":["planning meeting"]},{"id":"sprintgoal","g":"agile","word":"Sprint goal","text":"One sentence saying what a sprint is for. Small tasks can change along the way, as long as the goal is met.","also":["sprint goals"]},{"id":"sprintbacklog","g":"agile","word":"Sprint backlog","text":"The cards picked for the current sprint, with the team’s plan for doing them.","also":["sprint backlogs"]},{"id":"productbacklog","g":"agile","word":"Product backlog","text":"The full ordered list of everything that might be built for the product, most important at the top. It keeps changing as you learn.","also":["product backlogs"]},{"id":"productgoal","g":"agile","word":"Product goal","text":"The bigger result the product is working towards, which helps the team choose what to do next.","also":["product goals"]},{"id":"refinement","g":"agile","word":"Backlog refinement","text":"Regularly going through the backlog to tidy, split, order and add detail to cards, so they are ready to pick up. Also called backlog grooming.","also":["backlog grooming","refinement"]},{"id":"sprintreview","g":"agile","word":"Sprint review","text":"A meeting at the end of a sprint where the team shows what it finished and hears what people think, to decide what comes next.","also":["sprint reviews"]},{"id":"demo","g":"agile","word":"Demo","text":"Showing finished work working, live, to the people who asked for it.","also":["demos"],"noTip":1},{"id":"timebox","g":"agile","word":"Timebox","text":"A fixed amount of time for something. When it runs out you stop, even if not everything is done.","also":["timeboxed","timeboxes"]},{"id":"velocity","g":"agile","word":"Velocity","text":"How much work a team usually finishes in a sprint, used to plan how much to take on next time. It isn’t a score for how hard people work.","also":["team velocity"]},{"id":"capacity","g":"agile","word":"Capacity","text":"How much work the team can take on in a period, after holidays and other jobs.","noTip":1},{"id":"burndown","g":"agile","word":"Burndown chart","text":"A chart of the work left in a sprint going down day by day. If the line stays flat, something is stuck.","also":["burndown","burn-down chart"]},{"id":"burnup","g":"agile","word":"Burnup chart","text":"A chart of finished work going up over time, next to the total planned, so you can see when you will get there.","also":["burnup","burn-up chart"]},{"id":"kanbanboard","g":"agile","word":"Kanban board","text":"The board itself: a column for each stage of the work, with cards moving across.","also":["Kanban boards"]},{"id":"pullsys","g":"agile","word":"Pull system","text":"A way of working where new work only starts when someone has room to take it on, rather than being pushed onto a full plate.","also":["pull-based"]},{"id":"flow","g":"agile","word":"Flow","text":"How smoothly work moves across the board. Good flow means cards keep moving rather than piling up.","also":["flow of work"],"noTip":1},{"id":"leadtime","g":"agile","word":"Lead time","text":"How long it takes from someone asking for something to it being finished.","also":["lead times"]},{"id":"cycletime","g":"agile","word":"Cycle time","text":"How long a card takes from when work really starts on it to when it is finished.","also":["cycle times"]},{"id":"throughput","g":"agile","word":"Throughput","text":"How many cards get finished in a week, or in any set time.","also":["throughput rate"]},{"id":"bottleneck","g":"agile","word":"Bottleneck","text":"The one stage where work piles up and slows everything behind it, like the narrow neck of a bottle.","also":["bottlenecks"]},{"id":"swimlane","g":"agile","word":"Swimlane","text":"A row across the board that groups cards of one kind, such as urgent work or one team’s cards.","also":["swimlanes","swim lane"]},{"id":"lean","g":"agile","word":"Lean","text":"A way of working that cuts out waste (anything that doesn’t help the customer) and keeps work flowing."},{"id":"waste","g":"agile","word":"Waste","text":"In Lean, anything that takes effort but doesn’t help the customer, like waiting, rework or building things nobody uses.","noTip":1},{"id":"kaizen","g":"agile","word":"Continuous improvement","text":"Getting a little better all the time through small regular changes, then checking they helped. Retros are one way to do it. Also called kaizen.","also":["kaizen"]},{"id":"selforg","g":"agile","word":"Self-organising team","text":"A team that decides for itself how to do the work, rather than being told step by step.","also":["self-organising","self-managing team"]},{"id":"crossfunc","g":"agile","word":"Cross-functional team","text":"A team that has all the skills it needs to finish the work itself, like design, building and testing.","also":["cross-functional"]},{"id":"spike","g":"agile","word":"Spike","text":"A short, timeboxed bit of research to answer a question before committing to the real work.","also":["spikes"]},{"id":"rework","g":"agile","word":"Rework","text":"Doing work again because it wasn’t right the first time.","also":["reworked"]},{"id":"safe","g":"agile","word":"Scaled Agile (SAFe)","text":"Ways of using Agile across many teams in a big organisation. SAFe (the Scaled Agile Framework) is one well known example.","also":["scaled Agile"]},{"id":"repo","g":"build","word":"Repo","text":"Il-folder tal-kodiċi tal-proġett u l-istorja sħiħa tiegħu ta' commits, ġeneralment miżmum ukoll fuq GitHub.","also":["repository"]},{"id":"branch","g":"build","word":"Branch","text":"Linja separata ta' xogħol fil-kodiċi, biex isiru bidliet mingħajr ma tmiss il-verżjoni prinċipali.","also":["branches"]},{"id":"commit","g":"build","word":"Commit","text":"Snapshot issejvjat tal-kodiċi, b'nota qasira ta' x'inbidel. Dejjem tista' terġa' lura għal wieħed.","also":["commits"]},{"id":"push","g":"build","word":"Push","text":"Tibgħat snapshots issejvjati (commits) minn dan il-kompjuter fuq GitHub, biex ikunu ssejvjati u kondiviżi."},{"id":"merge","g":"build","word":"Merge","text":"Ngħaqqdu l-bidliet ta' branch lura mal-verżjoni prinċipali."},{"id":"pr","g":"build","word":"Pull request","text":"Titlob li l-bidliet ta' branch jiġu ċċekkjati u mgħaqqda mal-verżjoni prinċipali.","also":["PR"]},{"id":"refactor","g":"build","word":"Refactor","text":"Tirranġa l-kodiċi mingħajr ma tibdel dak li jagħmel: fajls iżgħar, ismijiet iktar ċari, inqas ripetizzjoni."},{"id":"bug","g":"build","word":"Bug","text":"Xi ħaġa li ma taħdimx kif suppost.","also":["bugs"]},{"id":"peerreview","g":"build","word":"Peer review","text":"Par għajnejn ieħor: AI oħra tiċċekkja x-xogħol ta' kull kard qabel ma tasal għandek, biex jgħaddu inqas żbalji.","also":["code review"]},{"id":"code","g":"build","word":"Code","text":"The written instructions that tell a computer what to do. Also called source code.","also":["source code"],"noTip":1},{"id":"proglang","g":"build","word":"Programming language","text":"A language for writing code, such as JavaScript, Python or Java. Different ones suit different jobs.","also":["programming languages"]},{"id":"developer","g":"build","word":"Developer (dev)","text":"Someone who writes and changes code. Also called a programmer or software engineer.","also":["developer","developers","programmer","programmers","software engineer"]},{"id":"software","g":"build","word":"Software","text":"Programs that run on computers and phones, as opposed to the machines themselves (the hardware).","noTip":1},{"id":"app","g":"build","word":"App","text":"Short for application: a program people use to get something done, on a phone, a computer or in a web browser.","also":["apps","application","applications"],"noTip":1},{"id":"webapp","g":"build","word":"Web app","text":"An app that runs in a web browser, so there is nothing to install.","also":["web apps","web application"]},{"id":"frontend","g":"build","word":"Front end","text":"The part of an app you see and click on: the screens, buttons and words, often in your browser.","also":["front-end","frontend"]},{"id":"backend","g":"build","word":"Back end","text":"The behind-the-scenes part of an app that keeps the data and does the work when you click something, like checking your password.","also":["back-end","backend"]},{"id":"fullstack","g":"build","word":"Full stack","text":"Working on both the front end and the back end.","also":["full-stack"]},{"id":"ui","g":"build","word":"User interface (UI)","text":"What a person sees and uses on screen: layout, buttons, menus and text.","also":["UI","user interface"]},{"id":"ux","g":"build","word":"User experience (UX)","text":"How it feels to use something: easy, clear and pleasant, or confusing and slow.","also":["UX","user experience"]},{"id":"accessibility","g":"build","word":"Accessibility (a11y)","text":"Making things usable by everyone, including people who can’t see well, can’t use a mouse or use a screen reader.","also":["a11y"]},{"id":"responsive","g":"build","word":"Responsive design","text":"Making pages fit and work well on any screen size, from a phone to a big monitor."},{"id":"designsys","g":"build","word":"Design system","text":"A shared kit of colours, fonts, buttons and rules, so every screen looks and behaves the same way.","also":["design systems"]},{"id":"architecture","g":"build","word":"Architecture","text":"The overall shape of a system: what the main parts are and how they talk to each other."},{"id":"database","g":"build","word":"Database (DB)","text":"An organised store of information, like a very powerful spreadsheet that the app can read and change.","also":["database","databases","DB"]},{"id":"schema","g":"build","word":"Database schema","text":"The layout of a database: which tables of information it has and what goes in each.","also":["schema"]},{"id":"sql","g":"build","word":"SQL","text":"Short for structured query language: the language used to ask many databases for information or to change it.","also":["Structured Query Language"]},{"id":"data","g":"build","word":"Data","text":"Information kept by a computer, like names, orders or settings.","also":["dataset","datasets"],"noTip":1},{"id":"server","g":"build","word":"Server","text":"A computer that is always on and answers requests from other computers, like sending a web page when you visit it.","also":["servers"]},{"id":"client","g":"build","word":"Client","text":"The side that asks for something, usually your browser or app, talking to a server. In business it also just means a customer.","also":["clients"],"noTip":1},{"id":"api","g":"build","word":"API","text":"Short for application programming interface: a set menu of requests one program can make to another, like asking a weather service for today’s forecast.","also":["APIs","application programming interface"]},{"id":"endpoint","g":"build","word":"Endpoint","text":"One item on an API’s menu: a web address a program can call to get or send something.","also":["endpoints"]},{"id":"integration","g":"build","word":"Integration","text":"Connecting two systems so they work together, like your shop sending orders to your accounts software.","also":["integrations"]},{"id":"webhook","g":"build","word":"Webhook","text":"A message one system sends to another by itself the moment something happens, like “payment received”.","also":["webhooks"]},{"id":"library","g":"build","word":"Library","text":"Ready-made code someone else wrote that you can reuse instead of writing it yourself.","also":["libraries"],"noTip":1},{"id":"framework","g":"build","word":"Framework","text":"A ready-made structure for building an app that decides much of how the code is laid out, like a house frame you fill in.","also":["frameworks"]},{"id":"sdk","g":"build","word":"Software development kit (SDK)","text":"A box of tools, code and examples for building software for one platform or service.","also":["SDK","SDKs"]},{"id":"softdep","g":"build","word":"Software dependency","text":"A library or tool your code needs to work. Keeping them up to date matters for safety.","also":["software dependencies"]},{"id":"package","g":"build","word":"Package","text":"A bundle of ready-made code you can install and use in a project.","also":["packages"],"noTip":1},{"id":"pkgmgr","g":"build","word":"Package manager","text":"A tool that fetches and updates the packages your code depends on. npm is a common one.","also":["package managers","npm"]},{"id":"git","g":"build","word":"Git","text":"The most widely used tool for keeping the history of code changes, as commits and branches."},{"id":"github","g":"build","word":"GitHub","text":"A website that keeps Git repos online, so teams can share code, review changes and track work."},{"id":"vcs","g":"build","word":"Version control","text":"Keeping a full history of every change to the files, so you can see who changed what and go back if needed. Git does this.","also":["source control","version control system"]},{"id":"clone","g":"build","word":"Clone","text":"Making your own full copy of a repo, with its history, on your computer.","also":["cloned","cloning"]},{"id":"pull","g":"build","word":"Pull","text":"Fetching the latest commits from the shared copy (like GitHub) onto your computer. The opposite of push.","also":["git pull"],"noTip":1},{"id":"mainbranch","g":"build","word":"Main branch","text":"The official version of the code that everyone works from, often called main or master.","also":["master branch"]},{"id":"conflict","g":"build","word":"Merge conflict","text":"When two changes touch the same lines in different ways, so the computer can’t join them and a person has to choose.","also":["merge conflicts"]},{"id":"diff","g":"build","word":"Diff","text":"A view showing exactly what changed between two versions: lines added and lines taken away.","also":["diffs"]},{"id":"fork","g":"build","word":"Fork","text":"Your own copy of someone else’s repo, which you can change without affecting theirs.","also":["forks","forked"]},{"id":"script","g":"build","word":"Script","text":"A short program that does one job by itself, like tidying files or starting the app.","also":["scripts"],"noTip":1},{"id":"build","g":"build","word":"Build","text":"Turning the code into something ready to run, or the ready-to-run result itself.","also":["builds"],"noTip":1},{"id":"compile","g":"build","word":"Compile","text":"Translating code people wrote into a form the computer can run directly.","also":["compiler"]},{"id":"cli","g":"build","word":"Command line (CLI)","text":"A text window where you type instructions for the computer instead of clicking. Also called the terminal.","also":["command line","command-line","CLI","terminal"]},{"id":"config","g":"build","word":"Configuration (config)","text":"The settings that control how software behaves, kept apart from the code so they are easy to change.","also":["config","configuration"],"noTip":1},{"id":"envvar","g":"build","word":"Environment variable","text":"A setting handed to a program when it starts, often used for addresses or passwords so they aren’t written into the code.","also":["environment variables","env var"]},{"id":"debugging","g":"build","word":"Debugging","text":"Hunting down why something isn’t working, and fixing it.","also":["debug","debugged"]},{"id":"pairing","g":"build","word":"Pair programming","text":"Two people (or a person and an AI) working on the same code together, one typing and one checking.","also":["pairing"]},{"id":"docs","g":"build","word":"Documentation (docs)","text":"Written explanations of how something works or how to use it.","also":["documentation","docs"],"noTip":1},{"id":"readme","g":"build","word":"README","text":"The first file to read in a repo: what the project is and how to get it running.","also":["READMEs"]},{"id":"legacy","g":"build","word":"Legacy system","text":"An older system still in use that is hard to change, often because few people still understand it.","also":["legacy systems","legacy code"]},{"id":"techdebt","g":"build","word":"Technical debt","text":"Shortcuts that save time now but make later changes slower, like a loan that builds up interest. Refactoring pays it down.","also":["tech debt"]},{"id":"test","g":"test","word":"Test","text":"Tipprova biċċa xogħol lesta biex tara li tagħmel dak li ntalab, qabel ma taċċettaha.","also":["testijiet","tittestja","jiġu ttestjati"],"noTip":1},{"id":"qa","g":"test","word":"QA","text":"Qosra għal quality assurance (assigurazzjoni tal-kwalità): il-kontrolli awtomatiċi li jsiru qabel ma xi ħaġa tmur live. Meta l-QA tkun ħamra, xi ħaġa falliet, u ma tistax tmur live sakemm tissewwa.","also":["kontrolli tal-kwalità"]},{"id":"testpile","g":"test","word":"Munzell tat-test","text":"Il-kards lesti li qed jistennewk tipprovahom, waħda wara l-oħra. Aċċetta waħda jew ibgħatha lura b'nota, u titla' dik li jmiss.","also":["munzelli tat-test"]},{"id":"autotest","g":"test","word":"Automated test","text":"A check the computer runs by itself every time the code changes, to catch mistakes early.","also":["automated tests","automatic tests"]},{"id":"manualtest","g":"test","word":"Manual test","text":"A person trying the work by hand to see if it behaves as it should.","also":["manual tests","manual testing"]},{"id":"unittest","g":"test","word":"Unit test","text":"A small automatic check of one tiny piece of code on its own.","also":["unit tests"]},{"id":"integtest","g":"test","word":"Integration test","text":"A check that several parts work properly together, not just one at a time.","also":["integration tests"]},{"id":"endtoend","g":"test","word":"End-to-end test (E2E)","text":"A test that acts like a real user from start to finish, such as signing up, buying and paying.","also":["E2E","end-to-end tests"]},{"id":"uat","g":"test","word":"User acceptance testing (UAT)","text":"The people who asked for the work try it themselves and say whether it does what they need. AI-gile’s test pile is its version of this.","also":["UAT","acceptance testing"]},{"id":"regression","g":"test","word":"Regression","text":"Something that used to work but broke after a change. Regression tests check that the old things still work.","also":["regressions","regression test","regression tests","regression testing"]},{"id":"smoke","g":"test","word":"Smoke test","text":"A very quick check that the main things work at all, for example right after a change goes live. If it fails, stop and look.","also":["smoke tests"]},{"id":"exploratory","g":"test","word":"Exploratory testing","text":"Trying the product freely and poking at it in different ways, to find problems that planned checks would miss.","also":["exploratory test","exploratory tests"]},{"id":"testcase","g":"test","word":"Test case","text":"One written scenario to try: the steps, and what should happen.","also":["test cases"]},{"id":"coverage","g":"test","word":"Test coverage","text":"How much of the code is checked by automatic tests. More is usually safer, but high coverage alone doesn’t prove it works well.","also":["code coverage"]},{"id":"testdata","g":"test","word":"Test data","text":"Made-up example information used while testing, so no real person’s private details are exposed.","also":["test fixtures"]},{"id":"edgecase","g":"test","word":"Edge case","text":"An unusual situation at the limits, like an empty form or a name with an apostrophe, where things often break.","also":["edge cases"]},{"id":"happypath","g":"test","word":"Happy path","text":"The normal route where everything goes right. Good testing also tries the unhappy paths."},{"id":"perftest","g":"test","word":"Performance testing","text":"Checking how fast something is and how well it copes under strain.","also":["performance test","performance tests"]},{"id":"loadtest","g":"test","word":"Load testing","text":"Checking how a system copes when lots of people use it at once.","also":["load test","load tests"]},{"id":"sectest","g":"test","word":"Security testing","text":"Looking for weaknesses that could let someone misuse a system or see what they shouldn’t.","also":["security test","security tests"]},{"id":"accesstest","g":"test","word":"Accessibility testing","text":"Checking that people with different abilities can use the product, including with a screen reader or only a keyboard.","also":["accessibility test"]},{"id":"linting","g":"test","word":"Linting","text":"An automatic check that spots likely mistakes and messy style in code, like a spelling checker for programs.","also":["linter","lint"]},{"id":"static","g":"test","word":"Static analysis","text":"Checking code for problems by reading it automatically, without running it.","also":["static code analysis"]},{"id":"flaky","g":"test","word":"Flaky test","text":"A test that sometimes passes and sometimes fails for no clear reason, so it can’t be fully trusted.","also":["flaky tests"]},{"id":"repro","g":"test","word":"Reproduce (repro)","text":"Making a bug happen again on purpose by following the same steps, so it can be studied and fixed. Writing those steps down is the most useful part of a bug report.","also":["repro","reproduce","steps to reproduce"]},{"id":"severity","g":"test","word":"Severity","text":"How bad a problem’s effect is, from a small annoyance to everything stopping.","also":["severity level"]},{"id":"deploy","g":"change","word":"Deploy","text":"Tqiegħed verżjoni ġdida live, pereżempju fuq server fejn in-nies jużawha."},{"id":"release","g":"change","word":"Release","text":"Pakkett b'isem ta' xogħol lest li jmur live flimkien, b'noti qosra fuq x'inbidel. 🚀 Releases jikteb in-noti mill-kards lesti.","also":["releases","rilaxx"]},{"id":"rollback","g":"change","word":"Rollback","text":"Tmur lura għall-aħħar verżjoni li kienet taħdem meta waħda ġdida toħloq problemi. F'AI-gile dan jagħmel checklist tal-passi biex tirreġġa' lura miktuba fuq kull bidla.","also":["roll back","erġa' lura","mreġġa' lura"]},{"id":"live","g":"change","word":"Live","text":"Il-verżjoni vera li n-nies jużaw, mhux kopja biex tipprova l-affarijiet. L-iżviluppaturi jsejħulha wkoll production.","also":["production","produzzjoni"],"noTip":1},{"id":"change","g":"change","word":"Bidla","text":"Bidla ppjanata f'xi ħaġa li n-nies jiddependu fuqha, miktuba minn qabel: x'inhi, għaliex, ir-riskju, meta, u kif tiġi mreġġa' lura. Ibda waħda b'🔀 Ressaq bidla.","also":["bidliet","talba għal bidla","talbiet għal bidla"],"noTip":1},{"id":"risk","g":"change","word":"Riskju","text":"Xi ħaġa li tista' tmur ħażin, b'punteġġ skont kemm hi probabbli u kemm tkun ħażina. ⚠️ Riskji jżommhom f'lista waħda, l-ogħla punteġġ l-ewwel, kull wieħed b'data biex terġa' tħares lejh.","also":["riskji","reġistru tar-riskji"]},{"id":"chgwin","g":"change","word":"Tieqa tal-bidliet","text":"Il-ħinijiet meta l-bidliet jistgħu jmorru live, bħal filgħaxija kwieta ta' nhar ta' Tlieta. Barra minn tieqa, kard tal-bidla ma tistax titlesta, sakemm ma tkunx emerġenza.","also":["twieqi tal-bidliet","tieqa"]},{"id":"gonogo","g":"change","word":"Go / no go","text":"Votazzjoni malajr eżatt qabel ma bidla tmur live: kull persuna li trid tapprova tgħid Go jew No go. Tmur 'il quddiem biss meta jaqblu.","also":["go/no go","go-no-go"]},{"id":"approval","g":"change","word":"Approvazzjoni","text":"Tistenna \"iva\" qabel ma jibda x-xogħol. Kard li jressaq xi ħabib, jew bidla, tistenna f'✅ Approvazzjonijiet sakemm tapprovaha jew tirrifjutaha.","also":["approvazzjonijiet"]},{"id":"quiettime","g":"change","word":"Ħin kwiet","text":"Perjodu, bħal stream, demo jew il-lejl, meta xejn ma jmur live. It-timijiet ikomplu jaħdmu u jittestjaw, imma l-mixja live tistenna sakemm jispiċċa. F'postijiet oħra jissejjaħ change freeze.","also":["ħinijiet kwieti","change freeze"]},{"id":"devops","g":"change","word":"DevOps","text":"A way of working where the people who build software and the people who run it work as one team, with lots of automation, so changes go live often and safely."},{"id":"cicd","g":"change","word":"CI/CD (continuous integration and delivery)","text":"Everyone’s changes are joined into the main version often and checked automatically each time (continuous integration), so the software is always ready to go live at the press of a button (continuous delivery).","also":["CI/CD","CI","CD","continuous integration","continuous delivery"]},{"id":"contdeploy","g":"change","word":"Continuous deployment","text":"One step further than continuous delivery: every change that passes the checks goes live by itself, with no button to press.","also":["continuous deployments"]},{"id":"pipeline","g":"change","word":"Pipeline","text":"The automatic series of steps a change goes through on its way to live, like build, test, then deploy.","also":["pipelines"]},{"id":"environment","g":"change","word":"Environment","text":"One separate copy of the system for one purpose, such as one to build in, one to test in and the live one.","also":["environments"],"noTip":1},{"id":"devenv","g":"change","word":"Development environment","text":"The copy a developer works in, often on their own computer, where breaking things harms nobody.","also":["dev environment"]},{"id":"testenv","g":"change","word":"Test environment","text":"A separate copy of the system used just for testing, so the real service isn’t touched.","also":["test environments"]},{"id":"staging","g":"change","word":"Staging","text":"A last copy set up just like live, for a final check before a change goes live.","also":["staging environment"]},{"id":"artifact","g":"change","word":"Build artifact","text":"The file or bundle a build produces, ready to be stored, checked or put live.","also":["build artifacts"]},{"id":"hotfix","g":"change","word":"Hotfix","text":"An urgent fix put live quickly, outside the normal plan, because something important is broken.","also":["hotfixes"]},{"id":"patch","g":"change","word":"Patch","text":"A small update that fixes a bug or closes a security hole. Applying security patches quickly matters.","also":["patches","security patch","security patches"]},{"id":"version","g":"change","word":"Version number","text":"A label like 2.4.1 that says which release you have. Often the first number changes for big changes and the last for small fixes.","also":["version numbers","semantic versioning"]},{"id":"relnotes","g":"change","word":"Release notes","text":"A short plain list of what changed in a release, for the people who use it, including fixes and known limits. Also called a changelog.","also":["changelog","change log"]},{"id":"flag","g":"change","word":"Feature flag","text":"An on and off switch for a feature, so new work can go live hidden and be turned on (or off again) without a new release.","also":["feature flags","feature toggle","feature toggles"]},{"id":"rollfwd","g":"change","word":"Roll forward","text":"Fixing a bad release by quickly putting out a new, corrected version instead of going back to the old one.","also":["rolling forward","rolled forward"]},{"id":"canary","g":"change","word":"Canary release","text":"Putting a change live for a small group first, and for everyone only once it looks fine. Named after the canaries miners took underground as an early warning.","also":["canary releases","canary"]},{"id":"bluegreen","g":"change","word":"Blue-green deployment","text":"Keeping two copies of the live system and switching people over to the new one in one go, so you can switch straight back if it goes wrong.","also":["blue-green","blue green deployment"]},{"id":"zerodown","g":"change","word":"Zero-downtime deployment","text":"Putting a new version live without the service ever stopping for its users.","also":["zero downtime","zero-downtime"]},{"id":"chgenable","g":"change","word":"Change enablement","text":"Helping changes succeed: weighing the risk, getting the right approval and picking a good time. Also called change management.","also":["change management"]},{"id":"cab","g":"change","word":"Change advisory board (CAB)","text":"A group that looks over important changes and agrees whether and when they may go ahead.","also":["CAB"]},{"id":"stdchange","g":"change","word":"Standard change","text":"A low-risk change done the same tried and tested way each time, so it is approved in advance.","also":["standard changes"]},{"id":"normchange","g":"change","word":"Normal change","text":"A change that needs to be checked and approved before it goes ahead.","also":["normal changes"]},{"id":"emergchange","g":"change","word":"Emergency change","text":"A change that must happen right away to fix or prevent serious trouble, with a quicker approval to match.","also":["emergency changes"]},{"id":"automation","g":"change","word":"Automation","text":"Getting the computer to do a repeated job by itself, so it is quicker and done the same way every time.","also":["automated"],"noTip":1},{"id":"infra","g":"change","word":"Infrastructure","text":"The machines, networks and services that software runs on.","also":["infra"]},{"id":"iac","g":"change","word":"Infrastructure as code (IaC)","text":"Describing your servers and settings in files kept with the code, so they can be rebuilt exactly the same way every time.","also":["IaC"]},{"id":"cloud","g":"change","word":"Cloud","text":"Renting computers, storage and services from a big provider over the internet, instead of owning the machines yourself.","also":["the cloud","cloud computing"]},{"id":"provider","g":"change","word":"Cloud provider","text":"A company that rents out computing over the internet, such as Amazon Web Services (AWS), Microsoft Azure or Google Cloud.","also":["cloud providers"]},{"id":"hosting","g":"change","word":"Hosting","text":"Where your app or website lives and runs so people can reach it, usually rented from a company."},{"id":"domain","g":"change","word":"Domain name","text":"The web address people type, like example.com. You rent it by the year, so it must be renewed.","also":["domain names","domain"]},{"id":"dns","g":"change","word":"DNS","text":"Short for domain name system: the internet’s address book, which turns a name like example.com into the address of the right computer.","also":["domain name system"]},{"id":"container","g":"change","word":"Container","text":"A sealed package holding an app and everything it needs, so it runs the same on any computer. Docker is the best known tool.","also":["containers","Docker"],"noTip":1},{"id":"vm","g":"change","word":"Virtual machine (VM)","text":"A pretend computer running inside a real one, so one big machine can act as many.","also":["VM","VMs","virtual machines"]},{"id":"serverless","g":"change","word":"Serverless","text":"Running code without looking after any servers yourself: the provider runs it when needed and you pay for what you use."},{"id":"lb","g":"change","word":"Load balancer","text":"Something that spreads visitors across several servers, so no single one gets overwhelmed.","also":["load balancers"]},{"id":"cache","g":"change","word":"Cache","text":"A handy store of recent results kept close by, so the same thing doesn’t have to be fetched or worked out again. Clearing it can fix pages that look out of date.","also":["caches","caching","cached"]},{"id":"cdn","g":"change","word":"Content delivery network (CDN)","text":"A worldwide set of servers holding copies of your pages and pictures near your visitors, so they load quickly.","also":["CDN"]},{"id":"migration","g":"change","word":"Migration","text":"Moving data or systems from an old setup to a new one, or carefully changing how a database is laid out.","also":["migrations","database migration"]},{"id":"service","g":"run","word":"Servizz","text":"Xi ħaġa li bnejt u li n-nies jiddependu fuqha, bħal websajt jew app, li tiġi mħarsa biex tibqa' taħdem. Immarka “Dan il-proġett huwa servizz” u għid x'joffri, min jużah u min hu on-call.","also":["servizzi","is-servizz"]},{"id":"uptimepct","g":"run","word":"Uptime","text":"How much of the time a service is working, usually as a percentage. 99.9% still allows about 43 minutes down a month.","also":["uptime percentage"]},{"id":"uptime","g":"run","word":"Uptime check","text":"Kontroll awtomatiku, kull ftit minuti, li s-servizz tiegħek għadu jwieġeb. Jekk jonqos diversi drabi wara xulxin, AI-gile jiftaħ kard ta' inċident waħdu.","also":["uptime","uptime checks","kontroll tal-uptime"]},{"id":"statuspage","g":"run","word":"Paġna tal-istatus","text":"Paġna pubblika li turi jekk servizz hux jaħdem (aħdar, oranġjo jew aħmar) bl-aħħar aġġornament, biex in-nies li jużawh ikunu jistgħu jiċċekkjaw minflok jistaqsu.","also":["paġni tal-istatus","status page"]},{"id":"desk","g":"run","word":"Service desk","text":"Fejn jidħlu l-mistoqsijiet u r-rapporti min-nies li jużaw is-servizz tiegħek. AI-gile jqassam kull wieħed bħala talba, inċident jew idea, u jgħidlek meta jidher qisu xi ħaġa li diġà ġiet irrappurtata.","also":["service desks","help desk","helpdesk","desk tas-servizz"]},{"id":"svcrequest","g":"run","word":"Talba għal servizz","text":"Xi ħadd jitlob xi ħaġa ordinarja, bħal kont ġdid jew ftit għajnuna, minflok jirrapporta li xi ħaġa nkisret. Tistenna d-dawra tagħha; l-inċident jgħaddi l-ewwel.","also":["talbiet għal servizz"]},{"id":"incident","g":"run","word":"Inċident","text":"Xi ħaġa li hija miksura għan-nies li qed jużawha bħalissa, bħall-websajt mitfija. Kard ta' 🔥 inċident taqbeż il-kju: li terġa' taħdem tiġi l-ewwel.","also":["inċidenti","l-inċident"]},{"id":"major","g":"run","word":"Inċident maġġuri","text":"Inċident kbir: ħafna nies affettwati, jew flus jew data f'riskju. Buttuna waħda tpoġġi kull tim fuqu (swarm), tqajjem lil min hu on-call u titlob aġġornament tal-istatus kull 30 minuta.","also":["inċidenti maġġuri"]},{"id":"oncall","g":"run","word":"On-call","text":"Tkun dak li jwieġeb meta xi ħaġa tinkiser, anke bil-lejl. Kull servizz għandu membru tat-tim on-call li jitqajjem l-ewwel għall-inċidenti tiegħu.","also":["on call"]},{"id":"replyby","g":"run","word":"Ħin biex titwieġeb","text":"Kemm kard tista' tistenna għall-ewwel tweġiba, pereżempju siegħa għal inċident. Wara dak il-ħin tieħu arloġġ aħmar, biex xejn ma jintesa bil-kwiet. Jissejjaħ ukoll mira ta' rispons.","also":["ħinijiet biex titwieġeb","mira ta' rispons","miri ta' rispons"]},{"id":"postmortem","g":"run","word":"Post-mortem","text":"Ħarsa qasira lura wara inċident: x'ġara, x'għen u x'għandu jinbidel, mingħajr ma tagħti tort lil ħadd. Inċident ma jistax jingħalaq mingħajrha.","also":["post-mortems","postmortem","reviżjoni wara l-inċident"]},{"id":"problem","g":"run","word":"Problema","text":"Il-kawża moħbija wara inċident wieħed jew aktar. Kard ta' 🧩 problema tiġbor flimkien inċidenti li jibqgħu jerġgħu jiġru, biex il-kawża tinstab u tissewwa għal dejjem.","also":["problemi","il-problema"],"noTip":1},{"id":"rootcause","g":"run","word":"Kawża ewlenija","text":"Ir-raġuni vera għaliex xi ħaġa nkisret, mhux biss dak li rajt imur ħażin. Sewwi l-kawża ewlenija u l-inċident ma jibqax jerġa' jiġri.","also":["kawżi ewlenin","root cause"]},{"id":"workaround","g":"run","word":"Workaround","text":"Mod kif iżżomm l-affarijiet jaħdmu sakemm it-tiswija vera tkun lesta, bħal tirristartja xi ħaġa meta teħel. Jinkiteb fuq il-kard tal-problema biex ħadd ma jkollu jerġa' jaħsibha.","also":["workarounds","soluzzjoni temporanja"]},{"id":"knownerror","g":"run","word":"Żball magħruf","text":"Problema li l-kawża tagħha hija mifhuma u għandha workaround, imma għadha mhix imsewwija. 🧩 Żbalji magħrufa jniżżilhom, biex kulħadd juża l-workaround minflok iħaffer mill-ġdid.","also":["żbalji magħrufa"]},{"id":"runbook","g":"run","word":"Runbook","text":"Struzzjonijiet pass pass biex issewwi tip ta' problema magħrufa, biex issir bl-istess mod, malajr, kull darba. Wara inċident kbir it-tim jista' jipproponi wieħed biex tagħtih l-OK.","also":["runbooks"]},{"id":"ci","g":"run","word":"Oġġett tal-konfigurazzjoni","text":"Ħaġa waħda li s-servizz tiegħek jiddependi minnha, bħal server, dominju, ċertifikat, ċavetta jew fornitur. 🗂️ Oġġetti tal-konfigurazzjoni jelenkahom għal kull servizz, biex tara x'jaffettwa inċident u x'jeħtieġ tiġdid jew backup.","also":["oġġetti tal-konfigurazzjoni"]},{"id":"expiry","g":"run","word":"Data ta' skadenza","text":"AI-gile iżomm għajnejh fuq dati bħal meta jiskadi ċertifikat jew dominju. 30 jum qabel id-data jagħmel kard waħda biex jiġġeddu, ħalli xejn ma jieqaf jaħdem għal għarrieda.","also":["dati ta' skadenza","skadenza","sorveljanza tal-iskadenzi"]},{"id":"backup","g":"run","word":"Backup","text":"Kopja salvata tad-data tiegħek minn qabel, biex terġa' għaliha jekk xi ħaġa tintilef jew issirilha l-ħsara. AI-gile jagħmel backup tal-bordijiet tiegħek kuljum.","also":["backups","back-up","back-ups"]},{"id":"restore","g":"run","word":"Irkupru","text":"Iġġib lura d-data minn backup. Backup verament jgħodd biss meta tkun taf li jista' jiġi rkuprat, għalhekk ta' min tipprovah kultant.","also":["irkupra","irkuprat","restore"]},{"id":"svcreview","g":"run","word":"Reviżjoni tas-servizz","text":"Ħarsa lura lejn xahar wieħed ta' servizz: inċidenti miftuħa u rranġati, kemm malajr in-nies kisbu tweġiba, uptime u tokens użati. Ir-Reviżjoni xahrija turih għal kull servizz.","also":["reviżjonijiet tas-servizz","reviżjoni xahrija","reviżjonijiet xahrin"]},{"id":"accessreview","g":"run","word":"Reviżjoni tal-aċċess","text":"Kull 90 jum tiċċekkja min għadu jista' jidħol: links ta' qsim, ir-rwoli tal-ħbieb u sigrieti miżmuma. Kull wieħed iżżommu jew tneħħih, ħalli aċċess qadim ma jibqax mitluq hemm.","also":["reviżjonijiet tal-aċċess"]},{"id":"improvements","g":"run","word":"Lista tat-titjib","text":"Dak kollu li t-tim iddeċieda li jtejjeb, f'post wieħed: suġġerimenti tar-retro, azzjonijiet tar-reviżjonijiet u soluzzjonijiet għal problemi, kull wieħed bl-istatus tiegħu. Issibha taħt 📈 Titjib.","also":["listi tat-titjib","titjib"]},{"id":"tokencap","g":"run","word":"Limitu ta' token","text":"Limitu kull xahar fuq it-tokens li l-aġenti ta' servizz jistgħu jużaw. Fi 80% tirċievi twissija; f'100% ix-xogħol fl-isfond tagħhom jistenna sax-xahar ta' wara jew sakemm togħla l-limitu.","also":["limiti ta' token"]},{"id":"svcmgmt","g":"run","word":"Service management","text":"Everything involved in keeping a service useful and working for the people who rely on it, day after day."},{"id":"itil","g":"run","word":"ITIL","text":"A widely used guide to good service management, covering things like incidents, problems and changes. The name once stood for IT Infrastructure Library."},{"id":"itsm","g":"run","word":"IT service management (ITSM)","text":"Running technology as a service for people, with clear ways to handle requests, incidents, changes and improvements.","also":["ITSM"]},{"id":"managed","g":"run","word":"Managed service","text":"A service someone else runs and looks after for you, under an agreement about how well it must work.","also":["managed services"]},{"id":"svcowner","g":"run","word":"Service owner","text":"The person who answers for a service as a whole: how well it works, what it costs and how it improves.","also":["service owners"]},{"id":"sla","g":"run","word":"Service level agreement (SLA)","text":"A written promise to customers about how well a service will work, like “up 99.9% of the time” or “answered within an hour”, often with money back if it is broken.","also":["SLA","SLAs","service level agreement"]},{"id":"slo","g":"run","word":"Service level objective (SLO)","text":"The team’s own target for how well a service should work over a period, usually set a bit stricter than the SLA to be safe.","also":["SLO","SLOs"]},{"id":"sli","g":"run","word":"Service level indicator (SLI)","text":"The actual measurement you check against a target, like the share of visits that loaded fine.","also":["SLI","SLIs"]},{"id":"availability","g":"run","word":"Availability","text":"Whether people can use a service when they need it, often measured as uptime.","also":["high availability"]},{"id":"downtime","g":"run","word":"Downtime","text":"Time when a service isn’t working or is switched off, planned or not.","also":["down time"]},{"id":"errorbudget","g":"run","word":"Error budget","text":"The small amount of failure your reliability target allows. While some is left you can take risks with changes; once it is used up, you slow down.","also":["error budgets"]},{"id":"outage","g":"run","word":"Outage","text":"A time when a service is down or badly broken for its users.","also":["outages"]},{"id":"degraded","g":"run","word":"Degraded","text":"Working, but badly: slow, or with some parts not working.","also":["degraded service"]},{"id":"monitoring","g":"run","word":"Monitoring","text":"Watching a service automatically all the time, so problems are spotted, ideally before users notice."},{"id":"observability","g":"run","word":"Observability","text":"How well you can tell what is going on inside a system from the outside, using its logs, numbers and traces.","also":["o11y"]},{"id":"log","g":"run","word":"Log","text":"A running diary a program keeps of what it is doing, used to work out what went wrong.","also":["logs","logging"],"noTip":1},{"id":"trace","g":"run","word":"Trace","text":"A record of how one request travels through the different parts of a system, step by step, showing where it slowed down.","also":["traces","tracing"]},{"id":"latency","g":"run","word":"Latency","text":"How long something takes to answer, like the wait between clicking and the page appearing."},{"id":"alert","g":"run","word":"Alert","text":"An automatic message that something needs attention, like the website not answering.","also":["alerts","alerting"],"noTip":1},{"id":"alertfatigue","g":"run","word":"Alert fatigue","text":"When there are so many alerts that people start ignoring them, including the important ones.","also":["alarm fatigue"]},{"id":"dashboard","g":"run","word":"Dashboard","text":"A screen showing the most important numbers and statuses at a glance.","also":["dashboards"],"noTip":1},{"id":"paging","g":"run","word":"Paging","text":"Urgently calling or waking the on-call person about a problem.","also":["paged"]},{"id":"escalation","g":"run","word":"Escalation","text":"Bringing in someone with more skill or authority when an issue can’t be sorted at the current level, or not fast enough.","also":["escalate","escalated"]},{"id":"triage","g":"run","word":"Triage","text":"Quickly sorting incoming issues by how urgent and important they are, so the worst gets handled first.","also":["triaged"]},{"id":"impact","g":"run","word":"Impact","text":"How much something affects people: how many, and how badly.","noTip":1},{"id":"urgency","g":"run","word":"Urgency","text":"How quickly something needs to be dealt with. Impact and urgency together set the priority.","noTip":1},{"id":"plevels","g":"run","word":"Priority levels (P1, P2…)","text":"Labels for how urgent an issue is. P1 is the most serious and needs action straight away.","also":["P1","P2","P3","P4"]},{"id":"queue","g":"run","word":"Ticket queue","text":"The list of requests and incidents waiting to be picked up.","also":["ticket queues"]},{"id":"tiers","g":"run","word":"First line and second line","text":"Levels of support: first line takes the call and fixes simple things; second line has deeper skills for harder ones. Also called tier 1 and tier 2.","also":["first-line support","tier 1","tier 2"]},{"id":"ic","g":"run","word":"Incident commander","text":"The one person who leads the response to an incident, so everyone knows who decides and who does what.","also":["incident commanders"]},{"id":"responsetime","g":"run","word":"Response time","text":"How long it takes before someone first picks up a request or incident.","also":["response times"]},{"id":"resolution","g":"run","word":"Resolution time","text":"How long it takes to fully sort out a request or incident, from report to fixed.","also":["resolution times","time to resolve"]},{"id":"mttr","g":"run","word":"Mean time to recover (MTTR)","text":"On average, how long it takes to get a service working again after it breaks. MTTR can mean slightly different things, so say what you measure.","also":["MTTR","mean time to restore"]},{"id":"mtbf","g":"run","word":"Mean time between failures (MTBF)","text":"On average, how long a service runs before something breaks.","also":["MTBF"]},{"id":"cmdb","g":"run","word":"Configuration management database (CMDB)","text":"The list of all your configuration items and how they connect, so you can see what depends on what.","also":["CMDB"]},{"id":"asset","g":"run","word":"Asset","text":"Anything of value you own or pay for to run the service, like a laptop, a software licence or a domain.","also":["assets"],"noTip":1},{"id":"capplan","g":"run","word":"Capacity planning","text":"Making sure there will be enough computer power, storage and people for what is coming.","also":["capacity plan"]},{"id":"scaling","g":"run","word":"Scaling","text":"Coping with more users by giving a machine more power (scaling up) or adding more machines (scaling out).","also":["scale up","scale out","scaling up","scaling out"]},{"id":"bcp","g":"run","word":"Business continuity","text":"Plans for keeping the important things going when something big goes wrong, like losing an office, a key supplier or the computers.","also":["business continuity plan"]},{"id":"dr","g":"run","word":"Disaster recovery (DR)","text":"The plan and tools for getting a service back after something serious, like losing a whole data centre.","also":["disaster recovery"]},{"id":"rto","g":"run","word":"Recovery time objective (RTO)","text":"The longest a service may be down after a disaster before it must be working again.","also":["RTO"]},{"id":"rpo","g":"run","word":"Recovery point objective (RPO)","text":"How much recent data you could afford to lose, measured in time. An RPO of one hour means backups at least every hour.","also":["RPO"]},{"id":"redundancy","g":"run","word":"Redundancy","text":"Having spares ready, like a second server, so one failure doesn’t stop the service."},{"id":"failover","g":"run","word":"Failover","text":"Switching over to a spare system by itself when the usual one fails.","also":["fail over"]},{"id":"spof","g":"run","word":"Single point of failure","text":"One part that takes everything down with it when it breaks, because there is no spare.","also":["single points of failure","SPOF"]},{"id":"maintwin","g":"run","word":"Maintenance window","text":"A planned time when a service may be paused or slow for upkeep, announced to users in advance.","also":["maintenance windows","planned maintenance"]},{"id":"handover","g":"run","word":"Handover","text":"Passing work, knowledge and responsibility to another person or team, so nothing gets dropped.","also":["handovers"]},{"id":"kb","g":"run","word":"Knowledge base","text":"A collection of help articles and answers, for users and for the team.","also":["knowledge bases"]},{"id":"csat","g":"run","word":"Customer satisfaction (CSAT)","text":"A score from users saying how happy they were, often asked after a request is closed.","also":["CSAT"]},{"id":"supplier","g":"run","word":"Supplier","text":"An outside company you rely on, like your hosting provider. Also called a vendor or third party.","also":["suppliers","vendor","vendors","third party"],"noTip":1},{"id":"retire","g":"run","word":"Service retirement","text":"Switching a service off for good, safely: telling its users, dealing with its data and access, and stopping its costs.","also":["retiring a service"]},{"id":"eol","g":"run","word":"End of life (EOL)","text":"When a product stops getting updates or support from its maker, so it should be replaced.","also":["EOL","end-of-life"]},{"id":"cybersec","g":"sec","word":"Cybersecurity","text":"Protecting systems and data from being broken into, stolen or damaged.","also":["cyber security"]},{"id":"authn","g":"sec","word":"Authentication","text":"Checking who someone is, usually with a password or a code. Often shortened to authn.","also":["authn"]},{"id":"authz","g":"sec","word":"Authorisation","text":"Checking what someone is allowed to do once you know who they are. Often shortened to authz.","also":["authz","authorization"]},{"id":"mfa","g":"sec","word":"Multi-factor authentication (MFA)","text":"Logging in with two or more proofs, like a password plus a code on your phone. Also called two-factor (2FA).","also":["MFA","2FA","two-factor","two-factor authentication"]},{"id":"sso","g":"sec","word":"Single sign-on (SSO)","text":"Logging in once to get into many systems, like using your work account everywhere.","also":["SSO"]},{"id":"pwmgr","g":"sec","word":"Password manager","text":"An app that creates strong passwords and remembers them for you.","also":["password managers"]},{"id":"secret","g":"sec","word":"Secret","text":"A password, key or other private code a program uses to get into something. It must never be shared or written into the code.","also":["secrets"],"noTip":1},{"id":"apikey","g":"sec","word":"API key","text":"A secret code that lets a program use another service’s API, and shows who is using (and paying for) it.","also":["API keys"]},{"id":"accesstoken","g":"sec","word":"Access token","text":"A temporary pass that proves a program is allowed in, so it doesn’t need your password each time. Not the same as an AI token.","also":["access tokens"]},{"id":"encryption","g":"sec","word":"Encryption","text":"Scrambling information so only someone with the right key can read it.","also":["encrypted","encrypt"]},{"id":"https","g":"sec","word":"HTTPS","text":"The secure way web pages travel, shown by the padlock in your browser, so nobody in between can read or change them."},{"id":"cert","g":"sec","word":"SSL/TLS certificate","text":"A digital ID card that lets a website prove who it is and use HTTPS. It expires, so it must be renewed.","also":["TLS certificate","SSL certificate","certificate","certificates"]},{"id":"permissions","g":"sec","word":"Permissions","text":"The rules for who may see or change what.","also":["permission"],"noTip":1},{"id":"leastpriv","g":"sec","word":"Least privilege","text":"Giving each person or program only the access they truly need, for only as long as they need it.","also":["principle of least privilege"]},{"id":"rbac","g":"sec","word":"Role-based access control (RBAC)","text":"Giving access by role, like viewer or editor, rather than person by person.","also":["RBAC","role-based access"]},{"id":"vuln","g":"sec","word":"Vulnerability","text":"A weakness that someone could use to break in or cause harm.","also":["vulnerabilities"]},{"id":"zeroday","g":"sec","word":"Zero-day","text":"A weakness attackers know about before the makers have had any time to fix it.","also":["zero-days","zero day"]},{"id":"malware","g":"sec","word":"Malware","text":"Harmful software, like viruses, made to damage, spy or steal."},{"id":"ransomware","g":"sec","word":"Ransomware","text":"Malware that locks up your files and demands money to unlock them. Good backups are the best defence.","also":["ransomware attack"]},{"id":"phishing","g":"sec","word":"Phishing","text":"Fake messages that try to trick you into giving away passwords or money, or opening something harmful.","also":["phishing email","phishing emails"]},{"id":"socialeng","g":"sec","word":"Social engineering","text":"Tricking people, rather than computers, into giving access, like a fake call from “IT support”."},{"id":"firewall","g":"sec","word":"Firewall","text":"A guard that decides which network traffic may come in or go out.","also":["firewalls"]},{"id":"vpn","g":"sec","word":"VPN","text":"Short for virtual private network: a private, scrambled link over the internet, often used to reach work systems safely.","also":["virtual private network"]},{"id":"ddos","g":"sec","word":"Denial of service (DoS, DDoS)","text":"Flooding a service with so much fake traffic that real people can’t use it. DDoS means it comes from many computers at once.","also":["DoS","DDoS","denial of service","DDoS attack"]},{"id":"pentest","g":"sec","word":"Penetration test (pen test)","text":"Hiring friendly experts to try to break in, so weaknesses are found before real attackers find them.","also":["pen test","pen testing","penetration testing","pentest"]},{"id":"audit","g":"sec","word":"Security audit","text":"A careful check of how well something is protected, against a list of good practice.","also":["security audits"]},{"id":"threatmodel","g":"sec","word":"Threat modelling","text":"Thinking through who might attack something, how, and what you would do to stop them.","also":["threat model","threat modeling"]},{"id":"breach","g":"sec","word":"Data breach","text":"When private information gets out to people who shouldn’t have it, or is lost or changed without permission.","also":["data breaches"]},{"id":"pii","g":"sec","word":"Personal data","text":"Any information about a person who can be identified, like a name, email address or location. Also called PII.","also":["PII","personally identifiable information"]},{"id":"gdpr","g":"sec","word":"GDPR","text":"The European law on personal data (the UK has its own version): collect only what you need, keep it safe, and let people see or delete theirs.","also":["General Data Protection Regulation"]},{"id":"dataprot","g":"sec","word":"Data protection","text":"Looking after personal data properly and within the law.","also":["data protection law"]},{"id":"privacypolicy","g":"sec","word":"Privacy policy","text":"A public page saying what personal data you collect, why, and what you do with it.","also":["privacy statement","privacy notice"]},{"id":"consent","g":"sec","word":"Consent","text":"A person’s clear, free yes to their data being used in a particular way. They can take it back at any time.","also":["opt-in"],"noTip":1},{"id":"cookie","g":"sec","word":"Cookie","text":"A small file a website saves in your browser to remember things, like being logged in. Some need your consent first.","also":["cookies"],"noTip":1},{"id":"minimisation","g":"sec","word":"Data minimisation","text":"Collecting and keeping only the personal data you really need for the job.","also":["data minimization"]},{"id":"retention","g":"sec","word":"Data retention","text":"How long data is kept before it is deleted. Keeping it no longer than needed is safer and often the law.","also":["retention period"]},{"id":"anon","g":"sec","word":"Anonymisation","text":"Changing data so nobody can reasonably be identified from it any more.","also":["anonymised","anonymization","anonymous data"]},{"id":"pseudo","g":"sec","word":"Pseudonymisation","text":"Swapping names and other details for codes, with a key kept apart to link them back. It is still personal data.","also":["pseudonymised","pseudonymization"]},{"id":"dpa","g":"sec","word":"Data processing agreement (DPA)","text":"A contract saying how a supplier may handle personal data on your behalf.","also":["DPA"]},{"id":"dpia","g":"sec","word":"Data protection impact assessment (DPIA)","text":"A careful look, before you start, at how a plan to use personal data could affect people and how to lower the risks.","also":["DPIA"]},{"id":"auditlog","g":"sec","word":"Audit log","text":"A record of who did what and when, so actions can be checked later.","also":["audit logs","audit trail"]},{"id":"compliance","g":"sec","word":"Compliance","text":"Following the laws, rules and standards that apply to you, and being able to show that you do.","also":["compliant"]},{"id":"iso","g":"sec","word":"ISO 27001","text":"A well known international standard for managing information security. Companies can be certified against it.","also":["ISO/IEC 27001"]},{"id":"soc","g":"sec","word":"SOC 2","text":"A US report, checked by outside auditors, showing a company looks after customer data properly.","also":["SOC2"]},{"id":"agent","g":"ai","word":"Aġent","text":"AI li taħdem waħedha fuq kompitu: taqra l-kodiċi, tagħmel bidliet, tmexxi kontrolli, u tirrapporta lura.","also":["aġenti","agent","agents"]},{"id":"token","g":"ai","word":"Token","text":"L-unità li biha jingħadd l-użu tal-AI: bejn wieħed u ieħor ftit ittri ta' test moqrija jew miktuba. Inqas tokens, aktar jibqa' mill-pjan tiegħek.","also":["tokens"]},{"id":"hook","g":"ai","word":"Hook","text":"Kmand żgħir li jaħdem waħdu f'mument stabbilit, eż. meta tibda sessjoni tal-AI, biex it-tim jisma' l-kummenti tiegħek.","also":["hooks"]},{"id":"ai","g":"ai","word":"Artificial intelligence (AI)","text":"Computer systems that do things we usually think need a person, like writing, answering questions or recognising pictures.","also":["AI","artificial intelligence"],"noTip":1},{"id":"ml","g":"ai","word":"Machine learning (ML)","text":"A way of making computers learn patterns from lots of examples, instead of giving them exact rules.","also":["machine learning"]},{"id":"model","g":"ai","word":"Model","text":"The trained “brain” of an AI system, built by learning from huge numbers of examples. Models differ in skill, speed and price.","also":["models","AI model"],"noTip":1},{"id":"llm","g":"ai","word":"Large language model (LLM)","text":"An AI model trained on vast amounts of text, so it can read and write language.","also":["LLM","LLMs"]},{"id":"genai","g":"ai","word":"Generative AI","text":"AI that creates new things, like text, pictures or code, rather than only sorting or spotting them.","also":["GenAI"]},{"id":"chatbot","g":"ai","word":"Chatbot","text":"A program you talk with in everyday language, by typing or speaking.","also":["chatbots"]},{"id":"prompt","g":"ai","word":"Prompt","text":"What you give an AI: your question or instructions, plus anything you hand it. Clearer prompts usually get better answers.","also":["prompts"]},{"id":"prompteng","g":"ai","word":"Prompt engineering","text":"The skill of writing prompts that get reliable, useful results."},{"id":"sysprompt","g":"ai","word":"System prompt","text":"Background instructions an AI gets before the conversation starts, setting its role and rules. They weigh more than what you type.","also":["system prompts","system instruction","system instructions"]},{"id":"context","g":"ai","word":"Context","text":"Everything the AI can see while it works: the instructions, your messages, files it has read and earlier replies.","noTip":1},{"id":"ctxwin","g":"ai","word":"Context window","text":"How much an AI can keep in mind at once, measured in tokens. Past that, older parts get dropped or summarised.","also":["context windows"]},{"id":"session","g":"ai","word":"Session","text":"One working conversation with an AI, from start to finish. A new session starts with a fresh memory.","also":["sessions"],"noTip":1},{"id":"memory","g":"ai","word":"Memory","text":"Notes an AI keeps between sessions, so it remembers your preferences and past decisions.","noTip":1},{"id":"hallucination","g":"ai","word":"Hallucination","text":"When an AI says something that sounds sure of itself but is made up or wrong. Check important facts.","also":["hallucinations","hallucinate","hallucinates"]},{"id":"training","g":"ai","word":"Training","text":"Teaching a model by showing it huge numbers of examples, before anyone uses it.","also":["trained"],"noTip":1},{"id":"trainingdata","g":"ai","word":"Training data","text":"The examples a model learned from. Its knowledge stops at the date that data was collected.","also":["training set"]},{"id":"cutoff","g":"ai","word":"Knowledge cutoff","text":"The date an AI’s built-in knowledge ends. It won’t know about later things unless it looks them up.","also":["training cutoff"]},{"id":"finetune","g":"ai","word":"Fine-tuning","text":"Extra training of an existing model on your own examples, to make it better at one particular job.","also":["fine-tune","fine-tuned","fine tuning"]},{"id":"inference","g":"ai","word":"Inference","text":"An AI model actually being used to answer something, as opposed to being trained.","also":["model inference"]},{"id":"tooluse","g":"ai","word":"Tool use","text":"An AI being able to do things, not just talk: run commands, read files or search the web, through tools the app gives it.","also":["tool calling","tool call","tool calls"]},{"id":"subagent","g":"ai","word":"Subagent","text":"A helper AI that a main AI hands a smaller job to, and gets the result back from.","also":["subagents","sub-agent"]},{"id":"multiagent","g":"ai","word":"Multi-agent","text":"Several AIs working together on one piece of work, each with its own part, like a small team.","also":["multi-agent system"]},{"id":"autonomy","g":"ai","word":"Autonomy","text":"How much an AI may do on its own before it has to ask a person.","also":["autonomous"]},{"id":"hitl","g":"ai","word":"Human in the loop","text":"Keeping a person involved to check or approve what the AI does at key points. In AI-gile that is you.","also":["human-in-the-loop","HITL"]},{"id":"guardrails","g":"ai","word":"Guardrails","text":"Limits and checks that keep an AI’s actions safe, like needing approval before anything goes live. They lower the risk of mistakes, but don’t rule them out.","also":["guardrail"]},{"id":"rag","g":"ai","word":"Retrieval-augmented generation (RAG)","text":"Letting an AI look things up in your own documents before it answers, so its answers rest on your facts.","also":["RAG","retrieval augmented generation"]},{"id":"embedding","g":"ai","word":"Embedding","text":"Turning text into a list of numbers that captures its meaning, so a computer can find things that mean similar things.","also":["embeddings"]},{"id":"vectordb","g":"ai","word":"Vector database","text":"A database built to search those lists of numbers (embeddings), to find material with a similar meaning.","also":["vector databases","vector store"]},{"id":"mcp","g":"ai","word":"Model Context Protocol (MCP)","text":"A common way to plug tools and data sources into AI apps, so an AI can use them.","also":["MCP"]},{"id":"temperature","g":"ai","word":"Temperature","text":"A setting for how adventurous an AI’s answers are. Low gives steadier, more predictable answers; high gives more varied ones. Neither makes it always right.","also":["model temperature"],"noTip":1},{"id":"multimodal","g":"ai","word":"Multimodal","text":"Able to work with more than one kind of information, such as text, pictures and sound.","also":["multi-modal"]},{"id":"evals","g":"ai","word":"Evaluation (eval)","text":"A planned test of how well an AI does on chosen examples, so you can compare models or prompts.","also":["eval","evals"]},{"id":"bias","g":"ai","word":"Bias","text":"When an AI (or a person) leans unfairly one way, often because of what it learned from.","also":["biased"],"noTip":1},{"id":"responsible","g":"ai","word":"Responsible AI","text":"Using AI fairly, safely and honestly, with people still answerable for the results.","also":["ethical AI"]},{"id":"injection","g":"ai","word":"Prompt injection","text":"A trick where hidden instructions in a web page or file try to make an AI do something its user didn’t ask for.","also":["prompt injections"]},{"id":"ratelimit","g":"ai","word":"Rate limit","text":"A cap on how many requests you may send to a service in a set time. Go over it and you have to wait.","also":["rate limits","rate limited"]},{"id":"usagelimit","g":"ai","word":"Usage limit","text":"How much AI work your plan allows in a period, after which it pauses or costs more.","also":["usage limits"]},{"id":"vibe","g":"ai","word":"Vibe coding","text":"Building software mostly by describing what you want to an AI and letting it write the code.","also":["vibe-coding"]},{"id":"budget","g":"money","word":"Budget","text":"The amount of money set aside for something.","also":["budgets"],"noTip":1},{"id":"costest","g":"money","word":"Cost estimate","text":"A best guess at what something will cost before you start.","also":["cost estimates"]},{"id":"roi","g":"money","word":"Return on investment (ROI)","text":"What you get back compared with what you put in. If it is positive, it was worth it.","also":["ROI"]},{"id":"tco","g":"money","word":"Total cost of ownership (TCO)","text":"Everything something really costs over its whole life, not just the price to buy it: running, support, upgrades and finally retiring it.","also":["TCO"]},{"id":"capex","g":"money","word":"CapEx and OpEx","text":"CapEx is money spent up front on things you keep; OpEx is ongoing spending, like monthly bills.","also":["CapEx","OpEx","capital expenditure","operating expenditure"]},{"id":"subscription","g":"money","word":"Subscription","text":"Paying regularly, usually monthly or yearly, to keep using something.","also":["subscriptions"],"noTip":1},{"id":"saas","g":"money","word":"Software as a service (SaaS)","text":"Software you use online and pay for by subscription, while the maker runs it for you.","also":["SaaS"]},{"id":"payg","g":"money","word":"Pay as you go","text":"Paying only for what you use, like cloud computing or AI tokens.","also":["pay-as-you-go","usage-based pricing"]},{"id":"overage","g":"money","word":"Overage","text":"Use above what your plan includes, which can cost extra.","also":["overages","overage charges"]},{"id":"billingalert","g":"money","word":"Billing alert","text":"A message when spending or use reaches a level you chose. It warns you, but doesn’t always stop further charges.","also":["billing alerts","spending alert"]},{"id":"freetier","g":"money","word":"Free tier","text":"A free level of a paid service, with limits. Handy for starting out.","also":["free plan"]},{"id":"pricing","g":"money","word":"Pricing plan","text":"The different packages a service sells, each with its own price and limits.","also":["pricing plans","price plan"]},{"id":"licence","g":"money","word":"Licence","text":"The rules for how you may use, copy, change or share something someone else made, such as software, fonts or pictures.","also":["licences","license","licenses"],"noTip":1},{"id":"opensource","g":"money","word":"Open source","text":"Software whose code anyone can read, use and often change for free, under the rules of its licence.","also":["open-source","open source software","OSS"]},{"id":"osslicence","g":"money","word":"Open source licence","text":"The rules that come with open source code. Some let you do almost anything (like MIT); some ask you to share your changes too (like GPL).","also":["open source licences","MIT licence","GPL"]},{"id":"proprietary","g":"money","word":"Proprietary","text":"Owned by a company and not free to copy or change. The opposite of open source.","also":["proprietary software"]},{"id":"copyright","g":"money","word":"Copyright","text":"The legal right of a creator to control copies of their work, including code and writing.","also":["copyrighted"],"noTip":1},{"id":"ip","g":"money","word":"Intellectual property (IP)","text":"Ideas and creations the law treats as owned, like code, designs, names and logos.","also":["intellectual property"]},{"id":"tos","g":"money","word":"Terms of service","text":"The rules you agree to when you use a service.","also":["terms and conditions","terms of use"]},{"id":"contract","g":"money","word":"Contract","text":"A written agreement between two sides that the law will back up.","also":["contracts"],"noTip":1},{"id":"sow","g":"money","word":"Statement of work (SOW)","text":"A document setting out exactly what work will be done, by when and for how much.","also":["SOW"]},{"id":"fixedprice","g":"money","word":"Fixed price","text":"An agreed price for the whole job, however long it takes.","also":["fixed-price"]},{"id":"tm","g":"money","word":"Time and materials","text":"Paying for the hours really worked and the things really used, rather than a set price.","also":["T&M"]},{"id":"invoice","g":"money","word":"Invoice","text":"A bill asking for payment for work done or goods supplied.","also":["invoices"],"noTip":1},{"id":"lockin","g":"money","word":"Vendor lock-in","text":"When moving away from a supplier is so hard or costly that you are stuck with them.","also":["lock-in"]},{"id":"procurement","g":"money","word":"Procurement","text":"The process of choosing and buying from suppliers."},{"id":"servicecredit","g":"money","word":"Service credit","text":"Money back or a discount you get when a supplier misses its SLA.","also":["service credits"]}]}};
